INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dave1010/tools/maps', 'community', 'dave1010', 'tools', 'dave1010/tools', 'maps', 0, 0, 20, '2026-02-18T01:08:43.420Z', '2026-02-18T04:25:33.116Z', NULL, '{"id":"dave1010/tools/maps","name":"maps","description":{"zh":"MapLibre 是一个地图开发工具集合。它提供了地图样式、脚本加载和导航控制等功能","ja":"MapLibre はマッピング開発ツールのコレクションです。マップスタイル、スクリプトの読み込み、ナビゲーションコントロールなどの機能を提供します","ko":"MapLibre는 지도 개발 도구의 모음입니다. 지도 스타일, 스크립트 로딩 및 네비게이션 컨트롤 등의 기능을 제공합니다","es":"MapLibre es una colección de herramientas para crear aplicaciones de cartografía. Incluye MapLibre GL y OpenFreeMap Liberty","fr":"MapLibre est un ensemble d''outils pour créer des applications de cartographie. Il inclut MapLibre GL et OpenFreeMap Liberty","de":"MapLibre ist eine Sammlung von Tools zur Erstellung von Kartierungsanwendungen. Enthält MapLibre GL und OpenFreeMap Liberty","pt":"O MapLibre é uma coleção de ferramentas de mapeamento que permitem criar experiências de usuário personalizadas","ru":"MapLibre - это коллекция инструментов картографии, позволяющая создавать персонализированные пользовательские trải nghiệm","ar":"MapLibre هي مجموعة من أدوات الخرائط التي تسمح بإنشاء تجارب مستخدم مخصصة","en":"Collection of tools"},"seo":{"title":{"zh":"MapLibre 地图开发工具","ja":"MapLibre マッピングツール","ko":"MapLibre 지도 개발 도구","es":"MapLibre: Herramientas de mapas para desarrolladores","fr":"MapLibre: Outils de cartographie pour développeurs","de":"MapLibre: Karten-Tools für Entwickler","pt":"Maps: Ferramentas de Mapeamento Avançadas","ru":"Карты: Коллекция Инструментов","ar":"الخرائط: مجموعة من الأدوات","en":"maps"},"description":{"zh":"MapLibre 是一个地图开发工具集合。它提供了地图样式、脚本加载和导航控制等功能","ja":"MapLibre はマッピング開発ツールのコレクションです。マップスタイル、スクリプトの読み込み、ナビゲーションコントロールなどの機能を提供します","ko":"MapLibre는 지도 개발 도구의 모음입니다. 지도 스타일, 스크립트 로딩 및 네비게이션 컨트롤 등의 기능을 제공합니다","es":"MapLibre es una colección de herramientas para crear aplicaciones de cartografía. Incluye MapLibre GL y OpenFreeMap Liberty","fr":"MapLibre est un ensemble d''outils pour créer des applications de cartographie. Il inclut MapLibre GL et OpenFreeMap Liberty","de":"MapLibre ist eine Sammlung von Tools zur Erstellung von Kartierungsanwendungen. Enthält MapLibre GL und OpenFreeMap Liberty","pt":"O MapLibre é uma coleção de ferramentas de mapeamento que permitem criar experiências de usuário personalizadas","ru":"MapLibre - это коллекция инструментов картографии, позволяющая создавать персонализированные пользовательские trải nghiệm","ar":"MapLibre هي مجموعة من أدوات الخرائط التي تسمح بإنشاء تجارب مستخدم مخصصة","en":"Collection of tools"},"definition":{"en":"Collection of tools"},"features":{"zh":["地图样式加载","脚本加载和初始化","导航控制添加","OpenFreeMap Liberty 样式支持","绝对定位的容器样式"],"ja":["マップスタイルの読み込み","スクリプトの読み込みと初期化","ナビゲーションコントロールの追加","OpenFreeMap Liberty スタイルのサポート","絶対位置付けのコンテナスタイル"],"ko":["지도 스타일 로딩","스크립트 로딩 및 초기화","네비게이션 컨트롤 추가","OpenFreeMap Liberty 스타일 지원","절대 위치의 컨테이너 스타일"],"es":["Incorporación de MapLibre GL","Uso de OpenFreeMap Liberty","Controles de navegación personalizables","Posicionamiento absoluto del contenedor de mapas","Carga de script desde unpkg.com"],"fr":["Intégration de MapLibre GL","Utilisation d''OpenFreeMap Liberty","Contrôles de navigation personnalisables","Positionnement absolu du conteneur de cartes","Chargement du script depuis unpkg.com"],"de":["Integration von MapLibre GL","Verwendung von OpenFreeMap Liberty","Anpassbare Navigationssteuerungen","Absolutes Positionieren des Kartencontainers","Laden des Skripts von unpkg.com"],"pt":["Inclusão do CSS do MapLibre","Carga do script do MapLibre","Uso do estilo OpenFreeMap Liberty","Adição de controles de navegação","Posicionamento absoluto do contêiner do mapa"],"ru":["Включение CSS MapLibre","Загрузка скрипта MapLibre","Использование стиля OpenFreeMap Liberty","Добавление контролей навигации","Абсолютное позиционирование контейнера карты"],"ar":["إدراج CSS MapLibre","تحميل سكربت MapLibre","استخدام نمط OpenFreeMap Liberty","إضافة عناصر تحكم في التنقل","التركيب المطلق لحاوية الخريطة"]},"keywords":{"zh":["MapLibre","地图开发","地图样式","脚本加载","导航控制","OpenFreeMap Liberty"],"ja":["MapLibre","マッピング開発","マップスタイル","スクリプトの読み込み","ナビゲーションコントロール","OpenFreeMap Liberty"],"ko":["MapLibre","지도 개발","지도 스타일","스크립트 로딩","네비게이션 컨트롤","OpenFreeMap Liberty"],"es":["MapLibre","cartografía","desarrollo de aplicaciones","herramientas de mapas","MapLibre GL","OpenFreeMap Liberty","controles de navegación","posicionamiento absoluto"],"fr":["MapLibre","cartographie","développement d''applications","outils de cartes","MapLibre GL","OpenFreeMap Liberty","contrôles de navigation","positionnement absolu"],"de":["MapLibre","Kartierung","Anwendungsentwicklung","Karten-Tools","MapLibre GL","OpenFreeMap Liberty","Navigationssteuerungen","absolutes Positionieren"],"pt":["MapLibre","Mapeamento","Ferramentas de mapeamento","Experiências de usuário personalizadas","Desenvolvimento web","Geolocalização"],"ru":["MapLibre","Картографии","Инструменты картографии","Персонализированные пользовательские trải nghiệm","Веб-разработка","Геолокация"],"ar":["MapLibre","الخرائط","أدوات الخرائط","تجارب مستخدم مخصصة","تطوير الويب","التحديد الجغرافي"]}},"owner":"dave1010","repo":"tools","repoPath":"dave1010/tools","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.420Z","topics":[],"category":"community","skillMd":{"name":"maps","description":"Use when building interactive map tools - Explains MapLibre setup, tiles, and common UI patterns.","bodyPreview":"## MapLibre basics\n\n- Include MapLibre''s CSS before your styles and load the script from https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js.\n- Keep the map container absolutely positioned to fill the viewport (see `#map` styles in `tools/map-explorer/index.html`).\n- Use the OpenFreeMap Liberty style (`https://tiles.openfreemap.org/styles/liberty`) unless a different basemap is required.\n- Add navigation controls with `map.addControl(new maplibregl.NavigationControl(), ''top-right'');`.\n- Guar","body":"## MapLibre basics\n\n- Include MapLibre''s CSS before your styles and load the script from https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js.\n- Keep the map container absolutely positioned to fill the viewport (see `#map` styles in `tools/map-explorer/index.html`).\n- Use the OpenFreeMap Liberty style (`https://tiles.openfreemap.org/styles/liberty`) unless a different basemap is required.\n- Add navigation controls with `map.addControl(new maplibregl.NavigationControl(), ''top-right'');`.\n- Guard against missing globals: if `typeof maplibregl === ''undefined''`, disable map-dependent UI and show an error.\n\n## Geolocation pattern\n\n- Provide a dedicated button for `navigator.geolocation.getCurrentPosition`.\n- Disable the button while locating, apply a loading state, and reset it in success/error callbacks.\n- On success, create or update a `maplibregl.Marker` and `map.easeTo` the new center.\n- On errors, surface user-friendly messages for permission, availability, and timeout cases.\n\n## Overlay & interaction tips\n\n- Keep status text in small, unobtrusive elements and update it via helper functions.\n\n## Accessibility & layout\n\n- Generally prefer maps that take up the whole viewport, with UI controls and panels overlayed\n- Footer links in an overlay too.\n"},"lastSynced":"2026-02-18T04:25:33.116Z","agentAnalysis":{"suitability":{"en":"Perfect for Geospatial Analysis Agents needing interactive map visualization capabilities with MapLibre","zh":"适合需要交互式地图可视化功能的空间分析代理，支持MapLibre","ja":"地理空間分析エージェントがMapLibreを使用したインタラクティブな地図視覚化機能を必要とする場合に最適","ko":"MapLibre를 사용한 대화형 맵 시각화 기능이 필요한 지리공간 분석 에이전트에 적합","es":"Perfecto para agentes de análisis geoespacial que necesitan capacidades de visualización de mapas interactivos con MapLibre","fr":"Parfait pour les agents d''analyse géospatiale ayant besoin de capacités de visualisation de cartes interactives avec MapLibre","de":"Perfekt für Geospatial-Analyse-Agenten, die interaktive Kartenvisualisierungsfunktionen mit MapLibre benötigen","pt":"Perfeito para Agentes de Análise Geoespacial que necessitam de capacidades de visualização de mapas interativos com MapLibre","ru":"Идеально подходит для агентов геопространственного анализа, которым необходимы функции интерактивной визуализации карт с помощью MapLibre","ar":"مثالي لعمليات تحليل الجغرافية المكانية التي تحتاج إلى قدرات للرسم التفاعلي للخرائط باستخدام MapLibre"},"recommendation":{"en":"Empowers agents to render custom basemaps using OpenFreeMap Liberty style and integrate navigation controls via maplibregl.NavigationControl, all while leveraging HTTPS protocol for secure script loading from unpkg.com","zh":"使代理能够使用OpenFreeMap Liberty样式渲染自定义底图，并通过maplibregl.NavigationControl集成导航控件，同时利用HTTPS协议从unpkg.com安全加载脚本","ja":"エージェントがOpenFreeMap Libertyスタイルを使用してカスタムベースマップをレンダリングし、maplibregl.NavigationControlを介してナビゲーションコントロールを統合することを可能にし、同時にunpkg.comからのセキュアなスクリプト読み込みのためにHTTPSプロトコルを利用","ko":"에이전트가 OpenFreeMap Liberty 스타일을 사용하여 사용자 정의 기본 맵을 렌더링하고 maplibregl.NavigationControl을 통해 네비게이션 컨트롤을 통합할 수 있으며,同時に unpkg.com에서 HTTPS 프로토콜을 사용하여 보안 스크립트 로딩","es":"Habilita a los agentes a renderizar mapas base personalizados utilizando el estilo OpenFreeMap Liberty y a integrar controles de navegación a través de maplibregl.NavigationControl, todo mientras aprovecha el protocolo HTTPS para una carga de secuencias de comandos segura desde unpkg.com","fr":"Permet aux agents de rendre des cartes de base personnalisées en utilisant le style OpenFreeMap Liberty et d''intégrer des contrôles de navigation via maplibregl.NavigationControl, le tout en exploitant le protocole HTTPS pour un chargement de script sécurisé à partir de unpkg.com","de":"Ermächtigt Agenten, benutzerdefinierte Basiskarten unter Verwendung des OpenFreeMap-Liberty-Stils zu rendern und Navigationssteuerungen über maplibregl.NavigationControl zu integrieren, während sie das HTTPS-Protokoll für eine sichere Skriptladung von unpkg.com nutzen","pt":"Habilita os agentes a renderizar mapas base personalizados usando o estilo OpenFreeMap Liberty e integrar controles de navegação via maplibregl.NavigationControl, tudo isso aproveitando o protocolo HTTPS para carregamento seguro de scripts a partir de unpkg.com","ru":"Наделяет агентов возможностью отображать пользовательские базовые карты, используя стиль OpenFreeMap Liberty, и интегрировать элементы управления навигацией через maplibregl.NavigationControl, все это при использовании протокола HTTPS для безопасной загрузки скриптов с unpkg.com","ar":"يمكن للوكلاء من خلالها تقديم خرائط قاعدة مخصصة باستخدام نمط OpenFreeMap Liberty وتكامل عناصر التحكم في الملاحة عبر maplibregl.NavigationControl، مع الاستفادة من بروتوكول HTTPS لتحميل البرامج النصية بشكل آمن من unpkg.com"},"useCases":{"en":["Visualizing geospatial data on interactive maps","Customizing map styles with OpenFreeMap Liberty","Integrating navigation controls for enhanced user experience"],"zh":["在交互式地图上可视化地理空间数据","使用OpenFreeMap Liberty自定义地图样式","集成导航控件以增强用户体验"],"ja":["インタラクティブな地図上で地理空間データを視覚化","OpenFreeMap Libertyを使用して地図スタイルをカスタマイズ","ナビゲーションコントロールを統合してユーザーエクスペリエンスを向上"],"ko":["대화형 맵에서 지리공간 데이터 시각화","OpenFreeMap Liberty를 사용하여 맵 스타일을 사용자 정의","네비게이션 컨트롤을 통합하여 사용자 경험 향상"],"es":["Visualizar datos geoespaciales en mapas interactivos","Personalizar estilos de mapa con OpenFreeMap Liberty","Integrar controles de navegación para una experiencia del usuario mejorada"],"fr":["Visualiser des données géospatiales sur des cartes interactives","Personnaliser les styles de carte avec OpenFreeMap Liberty","Intégrer des contrôles de navigation pour une expérience utilisateur améliorée"],"de":["Georäumliche Daten in interaktiven Karten visualisieren","Kartenstile mit OpenFreeMap Liberty anpassen","Navigationssteuerungen für eine verbesserte Benutzererfahrung integrieren"],"pt":["Visualizar dados geoespaciais em mapas interativos","Personalizar estilos de mapa com OpenFreeMap Liberty","Integrar controles de navegação para uma experiência do usuário aprimorada"],"ru":["Визуализация геопространственных данных на интерактивных картах","Настройка стилей карт с помощью OpenFreeMap Liberty","Интеграция элементов управления навигацией для улучшения пользовательского опыта"],"ar":["تجسيد البيانات الجغرافية المكانية على الخرائط التفاعلية","تخصيص أنماط الخرائط باستخدام OpenFreeMap Liberty","تكامل عناصر التحكم في الملاحة لتحسين تجربة المستخدم"]},"limitations":{"en":["Requires HTTPS connection for script loading","Dependent on MapLibre-gl@3.6.2 compatibility","Limited to OpenFreeMap Liberty style unless alternative basemap is specified"],"zh":["需要HTTPS连接来加载脚本","依赖于MapLibre-gl@3.6.2的兼容性","除非指定了替代的底图，否则仅限于OpenFreeMap Liberty样式"],"ja":["スクリプトの読み込みにはHTTPS接続が必要","MapLibre-gl@3.6.2の互換性に依存","代替ベースマップが指定されない限り、OpenFreeMap Libertyスタイルに限定"],"ko":["스크립트 로딩을 위해 HTTPS 연결이 필요","MapLibre-gl@3.6.2의 호환성에 의존","대체 기본 맵이 지정되지 않는 한 OpenFreeMap Liberty 스타일로 제한"],"es":["Requiere conexión HTTPS para la carga de secuencias de comandos","Dependiente de la compatibilidad de MapLibre-gl@3.6.2","Limitado al estilo OpenFreeMap Liberty a menos que se especifique un mapa base alternativo"],"fr":["Nécessite une connexion HTTPS pour le chargement de script","Dépend de la compatibilité de MapLibre-gl@3.6.2","Limité au style OpenFreeMap Liberty à moins qu''une carte de base alternative ne soit spécifiée"],"de":["Benötigt HTTPS-Verbindung für die Skriptladung","Abhängig von der Kompatibilität von MapLibre-gl@3.6.2","Begrenzt auf den OpenFreeMap-Liberty-Stil, es sei denn, eine alternative Basiskarte wird angegeben"],"pt":["Requer conexão HTTPS para carregamento de scripts","Dependente da compatibilidade do MapLibre-gl@3.6.2","Limitado ao estilo OpenFreeMap Liberty, a menos que seja especificado um mapa base alternativo"],"ru":["Требуется подключение HTTPS для загрузки скриптов","Зависит от совместимости MapLibre-gl@3.6.2","Ограничен стилем OpenFreeMap Liberty, если не указана альтернативная базовая карта"],"ar":["يتطلب الاتصال عبر بروتوكول HTTPS لتحميل البرامج النصية","يعتمد على توافق MapLibre-gl@3.6.2","محدود بنمط OpenFreeMap Liberty، إلا إذا تم تحديد خريطة قاعدة بديلة"]},"version":3},"qualityScore":20}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Aias/red-cliff-record/rcr-backend', 'community', 'Aias', 'red-cliff-record', 'Aias/red-cliff-record', 'rcr-backend', 0, 0, 55, '2026-02-18T01:08:43.420Z', '2026-02-18T04:26:05.156Z', NULL, '{"id":"Aias/red-cliff-record/rcr-backend","name":"rcr-backend","description":{"es":"RCR Backend es una plataforma de gestión de conocimiento personal que te permite almacenar y gestionar tus datos de forma local y segura","fr":"RCR Backend est une plateforme de gestion des connaissances personnelles qui vous permet de stocker et de gérer vos données de manière locale et sécurisée","de":"RCR Backend ist eine Plattform für persönliches Wissensmanagement, die es Ihnen ermöglicht, Ihre Daten lokal und sicher zu speichern und zu verwalten","pt":"O RCR Backend é uma abordagem local-first para gerenciamento de conhecimento pessoal, com foco em própria dados e segurança.","ru":"RCR Backend - это локальный подход к управлению личными знаниями, с упором на собственные данные и безопасность.","ar":"RCR Backend هو نهج محلي أولي لإدارة المعرفة الشخصية، مع التركيز على البيانات الشخصية والأمان.","en":"A local-first, own-your-data approach to personal knowledge management. The spiritual successor to barnsworthburning. "},"seo":{"title":{"es":"RCR Backend: Gestión de conocimiento personal","fr":"RCR Backend: Gestion des connaissances personnelles","de":"RCR Backend: Persönliches Wissensmanagement","pt":"RCR Backend: Gerenciamento de Conhecimento Pessoal","ru":"RCR Backend: Локальный подход к управлению личными знаниями","ar":"RCR Backend: إدارة المعرفة الشخصية المحلية","en":"rcr-backend"},"description":{"es":"RCR Backend es una plataforma de gestión de conocimiento personal que te permite almacenar y gestionar tus datos de forma local y segura","fr":"RCR Backend est une plateforme de gestion des connaissances personnelles qui vous permet de stocker et de gérer vos données de manière locale et sécurisée","de":"RCR Backend ist eine Plattform für persönliches Wissensmanagement, die es Ihnen ermöglicht, Ihre Daten lokal und sicher zu speichern und zu verwalten","pt":"O RCR Backend é uma abordagem local-first para gerenciamento de conhecimento pessoal, com foco em própria dados e segurança.","ru":"RCR Backend - это локальный подход к управлению личными знаниями, с упором на собственные данные и безопасность.","ar":"RCR Backend هو نهج محلي أولي لإدارة المعرفة الشخصية، مع التركيز على البيانات الشخصية والأمان.","en":"A local-first, own-your-data approach to personal knowledge management. The spiritual successor to barnsworthburning. "},"definition":{"en":"A local-first, own-your-data approach to personal knowledge management. The spiritual successor to barnsworthburning. "},"features":{"es":["Enfoque de gestión de conocimiento personal","Almacenamiento de datos local","Seguridad de los datos","Uso de Drizzle ORM","Soporte para TypeScript"],"fr":["Approche de gestion des connaissances personnelles","Stockage de données local","Sécurité des données","Utilisation de Drizzle ORM","Prise en charge de TypeScript"],"de":["Ansatz für persönliches Wissensmanagement","Lokale Daten-speicherung","Daten-sicherheit","Verwendung von Drizzle ORM","Unterstützung für TypeScript"],"pt":["Drizzle ORM para consultas de dados","Uso de sintaxe de consulta v2 do Drizzle","Suporte a relações e seleção de colunas","Evita SQL bruto com APIs de construtor de consultas","Mutations com insert, update e delete"],"ru":["Drizzle ORM для запросов данных","Использование синтаксиса запроса v2 Drizzle","Поддержка отношений и выбора столбцов","Избегайте сырого SQL с помощью API запросов","Мутации с insert, update и delete"],"ar":["Drizzle ORM لاستفسارات البيانات","استخدام بناء جملة الاستعلام v2 من Drizzle","دعم العلاقات واختيار الأعمدة","تجنب SQL الخام باستخدام واجهات برمجة تطبيقات بناء الاستفسار","التغييرات مع الإدراج والتحديث والحذف"]},"keywords":{"es":["RCR Backend","gestión de conocimiento personal","almacenamiento de datos local","seguridad de los datos","Drizzle ORM","TypeScript","desarrollo de software","tecnologías de desarrollo"],"fr":["RCR Backend","gestion des connaissances personnelles","stockage de données local","sécurité des données","Drizzle ORM","TypeScript","développement de logiciels","technologies de développement"],"de":["RCR Backend","persönliches Wissensmanagement","lokale Daten-speicherung","Daten-sicherheit","Drizzle ORM","TypeScript","Software-Entwicklung","Entwicklungs-technologien"],"pt":["RCR Backend","gerenciamento de conhecimento pessoal","Drizzle ORM","TypeScript","segurança de dados","local-first"],"ru":["RCR Backend","управление личными знаниями","Drizzle ORM","TypeScript","безопасность данных","локальный подход"],"ar":["RCR Backend","إدارة المعرفة الشخصية","Drizzle ORM","TypeScript","أمان البيانات","نهج محلي أولي"]}},"owner":"Aias","repo":"red-cliff-record","repoPath":"Aias/red-cliff-record","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.420Z","topics":[],"category":"community","skillMd":{"name":"rcr-backend","description":"Database, API, and integration conventions for Red Cliff Record. Use when working with Drizzle ORM, tRPC routers, database migrations, integration syncs, or media alt-text workflows in this project. Triggers on database queries, API routes, Drizzle v2, tRPC, Zod validation, integration work, or `rcr media` commands.","bodyPreview":"# RCR Backend\n\nSupplements global `typescript-guidelines` skill.\n\n## Drizzle ORM\n\n- **Always use Drizzle v2 query syntax** for reads: `db.query.<table>.findMany/findFirst` (not `db.select().from()`)\n  - Provides object-style `where`, built-in `with` for relations, and `columns` selection\n- Avoid raw SQL — use query builder APIs instead of `sql` template literals\n- Mutations: `db.insert()`, `db.update()`, `db.delete()`\n- Always upsert with `.onConflictDoUpdate()` on insertions\n- External-source P","body":"# RCR Backend\n\nSupplements global `typescript-guidelines` skill.\n\n## Drizzle ORM\n\n- **Always use Drizzle v2 query syntax** for reads: `db.query.<table>.findMany/findFirst` (not `db.select().from()`)\n  - Provides object-style `where`, built-in `with` for relations, and `columns` selection\n- Avoid raw SQL — use query builder APIs instead of `sql` template literals\n- Mutations: `db.insert()`, `db.update()`, `db.delete()`\n- Always upsert with `.onConflictDoUpdate()` on insertions\n- External-source PKs: `integer(''id'').primaryKey()` (not `serial`)\n- Never edit Drizzle meta files (`snapshot.json`, `_journal.json`) — they''re generated by `drizzle-kit`\n\n## tRPC\n\n- Routers live in `src/server/api/routers/`\n- Zod v4 for input validation\n- Client hooks from `src/app/trpc.ts`\n- Invalidate queries after mutations\n\n## Integrations\n\nCanonical guide: `INTEGRATIONS.md`.\n\n- Sync logic wrapped by `runIntegration`; exposed via `rcr sync <name>`\n- File convention: `types.ts` (Zod schemas), `client.ts` (API client), `sync.ts` (orchestration)\n- Respect rate limits; batch where needed; upsert for idempotency\n\n## Database Management\n\nCanonical operations: `README.md` and `src/server/db/db-manager.sh`.\n\n- `bun run db:migrate` / `bun run db:studio` for migrations and inspection\n- Never run destructive operations or migrations without explicit user permission\n\n## Agent Workflow: Media Alt Text\n\nThe `rcr media` commands support CLI-based alt text updates. Workflow for looped agents:\n\n1. **List** images needing alt text:\n   ```bash\n   rcr media list --type=image --alt-text=false --limit=100 --order=recordCreatedAt\n   ```\n2. **Get** item with parent record context:\n   ```bash\n   rcr media get <id> --with-record\n   ```\n   Returns media item plus `record: { id, title, type, mediaCaption, url }`.\n3. **Update**:\n   ```bash\n   rcr media update <id> ''{\"altText\": \"Description of the image\"}''\n   ```\n\n**Parallel processing**: pre-assign media IDs per agent to avoid overlap. Parent fetches a batch, splits into chunks, each subagent processes its assigned IDs.\n\nSchema: `media` table has `altText` (nullable), `url`, `type`, `width`, `height`, `recordId` (FK). ~4,090 images total.\n"},"lastSynced":"2026-02-18T04:26:05.156Z","qualityScore":55}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('atlanhq/atlan-sample-apps/atlan-sql-connector-patterns', 'community', 'atlanhq', 'atlan-sample-apps', 'atlanhq/atlan-sample-apps', 'atlan-sql-connector-patterns', 0, 0, 0, '2026-02-18T01:08:43.420Z', '2026-02-18T04:25:52.729Z', NULL, '{"id":"atlanhq/atlan-sample-apps/atlan-sql-connector-patterns","name":"atlan-sql-connector-patterns","description":{"zh":"Atlan SQL 连接器模式提供了一种选择合适的连接器策略并实现一致的连接的方法。通过使用 Atlan 应用程序 SDK 示例应用程序，开发者可以轻松实现连接器的集成","ja":"Atlan SQL コネクタ パターンは、適切なコネクタ戦略を選択し、一貫した接続を実装する方法を提供します。Atlan アプリケーション SDK のサンプル アプリケーションを使用すると、開発者はコネクタの統合を容易に実装できます","ko":"Atlan SQL 커넥터 패턴은 적합한 커넥터 전략을 선택하고 일관된 연결을 구현하는 방법을 제공합니다. Atlan 애플리케이션 SDK 샘플 애플리케이션을 사용하면 개발자가 커넥터의 통합을 쉽게 구현할 수 있습니다","es":"La aplicación de muestra Atlan SQL Connector Patterns utiliza Atlan Application SDK para elegir la estrategia de conector adecuada y implementarla de manera consistente.","fr":"L''application de démonstration Atlan SQL Connector Patterns utilise Atlan Application SDK pour choisir la stratégie de connecteur appropriée et la mettre en œuvre de manière cohérente.","de":"Die Beispielanwendung Atlan SQL Connector Patterns verwendet Atlan Application SDK, um die richtige Connector-Strategie auszuwählen und konsistent zu implementieren.","pt":"O Atlan SQL Connector Patterns é uma aplicação de exemplo construída com o Atlan Application SDK, que ajuda a escolher a estratégia de conector certa e implementá-la consistentemente.","ru":"Atlan SQL Connector Patterns - это пример приложения, построенного с помощью Atlan Application SDK, который помогает выбрать правильную стратегию соединителя и реализовать ее последовательно.","ar":"أنماط موصلات Atlan SQL هو تطبيق مثال مبني على Atlan Application SDK، يساعد في اختيار استراتيجية الموصل الصحيحة وتنفيذها بشكل متسق.","en":"Sample application built using Atlan Application SDK"},"seo":{"title":{"zh":"Atlan SQL 连接器模式 - 选择合适的连接器策略","ja":"Atlan SQL コネクタ パターン - 正しいコネクタ戦略を選択","ko":"Atlan SQL 커넥터 패턴 - 적합한 커넥터 전략 선택","es":"Patrones de Conector SQL Atlan","fr":"Modèles de Connecteur SQL Atlan","de":"Atlan SQL-Connector-Muster","pt":"Conectores SQL Atlan: Padrões e Implementação","ru":"Шаблоны соединителей Atlan SQL: выбор и реализация","ar":"أنماط موصلات Atlan SQL: الاختيار والتنفيذ","en":"atlan-sql-connector-patterns"},"description":{"zh":"Atlan SQL 连接器模式提供了一种选择合适的连接器策略并实现一致的连接的方法。通过使用 Atlan 应用程序 SDK 示例应用程序，开发者可以轻松实现连接器的集成","ja":"Atlan SQL コネクタ パターンは、適切なコネクタ戦略を選択し、一貫した接続を実装する方法を提供します。Atlan アプリケーション SDK のサンプル アプリケーションを使用すると、開発者はコネクタの統合を容易に実装できます","ko":"Atlan SQL 커넥터 패턴은 적합한 커넥터 전략을 선택하고 일관된 연결을 구현하는 방법을 제공합니다. Atlan 애플리케이션 SDK 샘플 애플리케이션을 사용하면 개발자가 커넥터의 통합을 쉽게 구현할 수 있습니다","es":"La aplicación de muestra Atlan SQL Connector Patterns utiliza Atlan Application SDK para elegir la estrategia de conector adecuada y implementarla de manera ...","fr":"L''application de démonstration Atlan SQL Connector Patterns utilise Atlan Application SDK pour choisir la stratégie de connecteur appropriée et la mettre en ...","de":"Die Beispielanwendung Atlan SQL Connector Patterns verwendet Atlan Application SDK, um die richtige Connector-Strategie auszuwählen und konsistent zu impleme...","pt":"O Atlan SQL Connector Patterns é uma aplicação de exemplo construída com o Atlan Application SDK, que ajuda a escolher a estratégia de conector certa e imple...","ru":"Atlan SQL Connector Patterns - это пример приложения, построенного с помощью Atlan Application SDK, который помогает выбрать правильную стратегию соединителя...","ar":"أنماط موصلات Atlan SQL هو تطبيق مثال مبني على Atlan Application SDK، يساعد في اختيار استراتيجية الموصل الصحيحة وتنفيذها بشكل متسق.","en":"Sample application built using Atlan Application SDK"},"definition":{"en":"Sample application built using Atlan Application SDK"},"features":{"zh":["支持 Postgres 和 Redshift 连接器","提供一致的连接实现","支持 SDK 重写和源特定行为","包含事实验证和端到端验证功能","支持 Atlan 应用程序 SDK","提供 decision-tree.md 参考文档"],"ja":["Postgres と Redshift コネクタをサポート","一貫した接続の実装を提供","SDK の書き換えとソース固有の動作をサポート","ファクト検証とエンドツーエンド検証機能を含む","Atlan アプリケーション SDK をサポート","decision-tree.md 参考ドキュメントを提供"],"ko":["Postgres 및 Redshift 커넥터 지원","일관된 연결 구현 제공","SDK 재작성 및 소스 특정 동작 지원","팩트 검증 및 종단 간 검증 기능 포함","Atlan 애플리케이션 SDK 지원","decision-tree.md 참조 문서 제공"],"es":["Estrategias de conector personalizadas","Implementación de componentes requeridos","Verificación de autenticación y prefiltro","Transformación de comportamiento y mapa de flujo de trabajo"],"fr":["Stratégies de connecteur personnalisées","Mise en œuvre de composants requis","Vérification de l''authentification et du prefiltro","Transformation du comportement et de la carte de flux de travail"],"de":["Benutzerdefinierte Connector-Strategien","Implementierung erforderlicher Komponenten","Überprüfung der Authentifizierung und des Prefilters","Transformation des Verhaltens und der Workflow-Karte"],"pt":["Escolha da estratégia de conector certa","Implementação consistente com o Atlan Application SDK","Verificação de autenticação e pré-voo","Mapeamento de fluxo de trabalho e transformação de comportamento","Validação de contrato de ponta a ponta"],"ru":["Выбор правильной стратегии соединителя","Последовательная реализация с помощью Atlan Application SDK","Проверка аутентификации и предполета","Картирование рабочего процесса и преобразование поведения","Валидация контракта от начала до конца"],"ar":["اختيار استراتيجية الموصل الصحيحة","التنفيذ المتسق باستخدام Atlan Application SDK","التحقق من المصادقة والتحليق المسبق","خريطة سير العمل وتحويل السلوك","التحقق من صحة العقد من البداية إلى النهاية"]},"keywords":{"zh":["Atlan SQL 连接器模式","Atlan 应用程序 SDK","连接器策略","一致连接","Postgres","Redshift","SDK 重写","源特定行为"],"ja":["Atlan SQL コネクタ パターン","Atlan アプリケーション SDK","コネクタ戦略","一貫した接続","Postgres","Redshift","SDK の書き換え","ソース固有の動作"],"ko":["Atlan SQL 커넥터 패턴","Atlan 애플리케이션 SDK","커넥터 전략","일관된 연결","Postgres","Redshift","SDK 재작성","소스 특정 동작"],"es":["Conector SQL","Atlan Application SDK","Estrategias de conector","Implementación de conector","Verificación de autenticación","Transformación de comportamiento"],"fr":["Connecteur SQL","Atlan Application SDK","Stratégies de connecteur","Mise en œuvre de connecteur","Vérification de l''authentification","Transformation du comportement"],"de":["SQL-Connector","Atlan Application SDK","Connector-Strategien","Implementierung von Connectors","Überprüfung der Authentifizierung","Transformation des Verhaltens"],"pt":["Atlan SQL Connector Patterns","Conectores SQL","Atlan Application SDK","Desenvolvimento de aplicações","Integração de dados","Estratégia de conector","Implementação consistente","Verificação de autenticação"],"ru":["Atlan SQL Connector Patterns","Соединители SQL","Atlan Application SDK","Разработка приложений","Интеграция данных","Стратегия соединителя","Последовательная реализация","Проверка аутентификации"],"ar":["أنماط موصلات Atlan SQL","موصلات SQL","Atlan Application SDK","تطوير التطبيقات","تكامل البيانات","استراتيجية الموصل","التنفيذ المتسق","التحقق من المصادقة"]}},"owner":"atlanhq","repo":"atlan-sample-apps","repoPath":"atlanhq/atlan-sample-apps","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.420Z","topics":[],"category":"community","skillMd":{"name":"atlan-sql-connector-patterns","description":"Select and apply the correct SQL connector implementation pattern (SDK-default minimal or source-specific custom). Use when building or extending SQL metadata/query extraction connectors.","bodyPreview":"# Atlan SQL Connector Patterns\n\nChoose the right connector strategy and implement it consistently.\n\n## Workflow\n1. Use `references/decision-tree.md` to choose `postgres-minimal` or `redshift-custom`.\n2. Implement required components for selected path.\n3. Verify auth, preflight, workflow map, and transformation behavior against references.\n4. Run `atlan-fact-verification-gate` if requirements imply source-specific behavior or SDK override risk.\n5. Hand off to `atlan-e2e-contract-validator` for co","body":"# Atlan SQL Connector Patterns\n\nChoose the right connector strategy and implement it consistently.\n\n## Workflow\n1. Use `references/decision-tree.md` to choose `postgres-minimal` or `redshift-custom`.\n2. Implement required components for selected path.\n3. Verify auth, preflight, workflow map, and transformation behavior against references.\n4. Run `atlan-fact-verification-gate` if requirements imply source-specific behavior or SDK override risk.\n5. Hand off to `atlan-e2e-contract-validator` for contract generation.\n\n## Rules\n- Default to minimal path unless requirements justify custom path.\n- For custom path, explicitly document why SDK defaults are insufficient.\n- Reuse source-specific patterns only when corresponding requirements are present.\n\n## References\n- Decision tree: `references/decision-tree.md`\n- Shared verification map: `../_shared/references/verification-sources.md`\n"},"lastSynced":"2026-02-18T04:25:52.729Z","qualityScore":0}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('camronh/EZVals/ship', 'community', 'camronh', 'EZVals', 'camronh/EZVals', 'ship', 0, 0, 30, '2026-02-18T01:58:18.370Z', '2026-02-18T05:15:45.680Z', NULL, '{"id":"camronh/EZVals/ship","name":"ship","description":{"zh":"Ship 是一个简单但强大的代码优先评估框架，提供了代码评估和测试的步骤指南","ja":"Ship は、コード評価とテストのためのステップバイステップガイドを提供する、シンプルながら強力なコードファースト評価フレームワークです","ko":"Ship은 코드 평가와 테스트를 위한 단계별 가이드를 제공하는 간단하지만 강력한 코드 우선 평가 프레임워크입니다","es":"Ship es un marco de evaluación de código simple pero potente que te permite confirmar, probar y versionar tu código de manera eficiente","fr":"Ship est un cadre d''évaluation de code simple mais puissant qui vous permet de confirmer, de tester et de versionner votre code de manière efficace","de":"Ship ist ein einfaches aber leistungsfähiges Code-Evaluierungsframework, das es Ihnen ermöglicht, Ihren Code zu bestätigen, zu testen und zu versionieren","pt":"O Ship é um framework de avaliação de código simples e poderoso que ajuda a melhorar a produtividade de desenvolvimento","ru":"Ship - это простой но мощный фреймворк для оценки кода, который помогает улучшить производительность разработки","ar":"Ship هو إطار تقييم رمز بسيط ولكن قوي يساعد على تحسين إنتاجية التطوير","en":"Simple but powerful code-first eval framework"},"seo":{"title":{"zh":"Ship: 代码优先评估框架","ja":"Ship: コードファースト評価フレームワーク","ko":"Ship: 코드 우선 평가 프레임워크","es":"Ship: Marco de Evaluación de Código","fr":"Ship: Cadre d''Évaluation de Code","de":"Ship: Code-Evaluierungsframework","pt":"Ship: Framework de Avaliação de Código","ru":"Ship: Простой но мощный фреймворк для оценки кода","ar":"Ship: إطار تقييم رمز بسيط ولكن قوي","en":"ship"},"description":{"zh":"Ship 是一个简单但强大的代码优先评估框架，提供了代码评估和测试的步骤指南","ja":"Ship は、コード評価とテストのためのステップバイステップガイドを提供する、シンプルながら強力なコードファースト評価フレームワークです","ko":"Ship은 코드 평가와 테스트를 위한 단계별 가이드를 제공하는 간단하지만 강력한 코드 우선 평가 프레임워크입니다","es":"Ship es un marco de evaluación de código simple pero potente que te permite confirmar, probar y versionar tu código de manera eficiente","fr":"Ship est un cadre d''évaluation de code simple mais puissant qui vous permet de confirmer, de tester et de versionner votre code de manière efficace","de":"Ship ist ein einfaches aber leistungsfähiges Code-Evaluierungsframework, das es Ihnen ermöglicht, Ihren Code zu bestätigen, zu testen und zu versionieren","pt":"O Ship é um framework de avaliação de código simples e poderoso que ajuda a melhorar a produtividade de desenvolvimento","ru":"Ship - это простой но мощный фреймворк для оценки кода, который помогает улучшить производительность разработки","ar":"Ship هو إطار تقييم رمز بسيط ولكن قوي يساعد على تحسين إنتاجية التطوير","en":"Simple but powerful code-first eval framework"},"definition":{"en":"Simple but powerful code-first eval framework"},"features":{"zh":["代码评估和测试","自动化测试","版本更新","代码优先评估","简单易用"],"ja":["コード評価とテスト","自動テスト","バージョン更新","コードファースト評価","シンプルで使いやすい"],"ko":["코드 평가와 테스트","자동 테스트","버전 업데이트","코드 우선 평가","간단하고 사용하기 쉬운"],"es":["Confirmación en la rama de desarrollo","Ejecución de pruebas en paralelo","Actualización de versiones","Gestión de cambios en el registro de cambios"],"fr":["Confirmation sur la branche de développement","Exécution de tests en parallèle","Mise à jour des versions","Gestion des changements dans le journal des modifications"],"de":["Bestätigung auf der Entwicklungszweig","Ausführung von Tests in Parallel","Aktualisierung von Versionen","Verwaltung von Änderungen im Änderungsprotokoll"],"pt":["Confirmação no branch de desenvolvimento","Execução de testes em paralelo","Atualização do changelog","Controle de versão automático","Integração com pipelines de desenvolvimento"],"ru":["Подтверждение на ветке разработки","Параллельное выполнение тестов","Обновление changelog","Автоматический контроль версий","Интеграция с конвейерами разработки"],"ar":["التأكيد على فرع التطوير","تشغيل الاختبارات بالتوازي","تحديث سجل التغييرات","مراقبة الإصدارات تلقائيًا","التكامل مع أنابيب التطوير"]},"keywords":{"zh":["代码优先评估","代码评估框架","自动化测试","版本更新","代码测试","开发工具"],"ja":["コードファースト評価","コード評価フレームワーク","自動テスト","バージョン更新","コードテスト","開発ツール"],"ko":["코드 우선 평가","코드 평가 프레임워크","자동 테스트","버전 업데이트","코드 테스트","개발 도구"],"es":["evaluación de código","desarrollo de software","pruebas de software","versionamiento","gestión de cambios","desarrollo ágil"],"fr":["évaluation de code","développement de logiciels","tests de logiciels","versionnage","gestion de changements","développement agile"],"de":["Code-Evaluierung","Software-Entwicklung","Software-Tests","Versionierung","Änderungsmanagement","Agile Entwicklung"],"pt":["framework de avaliação de código","desenvolvimento de software","testes em paralelo","controle de versão","pipelines de desenvolvimento","produtividade de desenvolvimento"],"ru":["фреймворк для оценки кода","разработка программного обеспечения","параллельное тестирование","контроль версий","конвейеры разработки","производительность разработки"],"ar":["إطار تقييم رمز","تطوير البرمجيات","اختبارات متوازية","مراقبة الإصدارات","أنابيب التطوير","إنتاجية التطوير"]}},"owner":"camronh","repo":"EZVals","repoPath":"camronh/EZVals","stars":0,"forks":0,"updatedAt":"2026-02-18T01:58:18.370Z","topics":[],"category":"community","skillMd":{"name":"ship","description":"Ship dev to main. Creates a release with version bump, changelog, and tag.","bodyPreview":"Follow these steps in order:\n\n## 1. Confirm on Dev\n\n- Verify we''re on the `dev` branch\n- If not, stop and ask\n\n## 2. Run Tests\n\n- Run tests and ensure all tests pass. (Use `-n auto` to run tests in parallel)\n- If tests fail, STOP and report the failures\n\n## 3. Version Bump\n\n- Read `docs/changelog.mdx` to see what''s in the `## Unreleased` section\n- Suggest the next version (based on existing versions in the changelog)\n- Update `docs/changelog.mdx`: change `## Unreleased` to `## <version> - <today","body":"Follow these steps in order:\n\n## 1. Confirm on Dev\n\n- Verify we''re on the `dev` branch\n- If not, stop and ask\n\n## 2. Run Tests\n\n- Run tests and ensure all tests pass. (Use `-n auto` to run tests in parallel)\n- If tests fail, STOP and report the failures\n\n## 3. Version Bump\n\n- Read `docs/changelog.mdx` to see what''s in the `## Unreleased` section\n- Suggest the next version (based on existing versions in the changelog)\n- Update `docs/changelog.mdx`: change `## Unreleased` to `## <version> - <today''s date>`\n- Update `pyproject.toml` version to match\n\n## 4. Update Skill Version\n\n- Update the version comment in `ezvals/skills/evals/SKILL.md` (the `<!-- Version: X.X.X -->` line) to match the release version\n- The skill version **MUST** match the release tag — the Sync Skill to Marketplace workflow will fail otherwise\n\n## 5. Commit & Push Dev\n\n```bash\ngit add -A\ngit commit -m \"release <version>\"\ngit push origin dev\n```\n\n## 6. Merge to Main\n\n```bash\ngit checkout main\ngit pull origin main\ngit merge dev\ngit push origin main\n```\n\n## 7. Tag & Push\n\n```bash\ngit tag v<version>\ngit push origin v<version>\n```\n\n## 8. Return to Dev\n\n```bash\ngit checkout dev\n```\n\n## PyPI Publishing (Automatic)\n\nPublishing to PyPI is handled automatically by GitHub Actions:\n\n- **Dev builds** (`.github/workflows/publish-dev.yml`): Every push to `main` publishes a dev version (`0.0.0.dev{timestamp}`) to PyPI\n- **Release builds** (`.github/workflows/publish.yml`): Pushing a tag like `v0.1.0` triggers a release publish to PyPI\n\nYou don''t need to manually run `uv publish` - just push the tag and the workflow handles it.\n\n## Error Handling\n\n- If tests fail → stop and report\n- If merge conflicts occur → stop and ask for help\n- If not on dev → stop and ask\n"},"lastSynced":"2026-02-18T05:15:45.680Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Workflow Agents automating code deployment pipelines.","zh":"非常适合开发工作流代理自动化代码部署管道。","ja":"開発ワークフロー エージェントによるコードのデプロイ パイプラインの自動化に最適です。","ko":"코드 배포 파이프라인을 자동화하는 개발 워크플로 에이전트에 적합합니다.","es":"Perfecto para Agentes de flujo de trabajo de desarrollo que automatizan las tuberías de implementación de código.","fr":"Parfait pour les agents de workflow de développement qui automatisent les pipelines de déploiement de code.","de":"Perfekt für Entwicklung-Workflow-Agents, die Code-Deploy-Pipelines automatisieren.","pt":"Perfeito para Agentes de Fluxo de Desenvolvimento que automatizam pipelines de implantação de código.","ru":"Идеально подходит для агентов рабочего процесса разработки, автоматизирующих конвейеры развертывания кода.","ar":"مثالي لعمليات وكيلflux التطوير التي تautomate أنابيبcode النشر."},"recommendation":{"en":"Enables automated code-first evaluation workflows with branch verification, parallel test execution, and changelog management. Provides deterministic version bumping based on semantic versioning patterns in documentation.","zh":"启用自动代码优先评估工作流，具有分支验证、并行测试执行和变更日志管理。根据文档中的语义版本模式提供确定性的版本升级。","ja":"自動コード優先評価ワークフローを有効にし、ブランチの検証、並列テストの実行、変更ログの管理を提供します。ドキュメント内のセマンティック バージョニング パターンに基づいて決定的なバージョン バンプを提供します。","ko":"자동 코드 우선 평가 워크플로우를 활성화하여 분기 확인, 병렬 테스트 실행 및 변경 로그 관리를 제공합니다. 문서의 의미 버전 지정 패턴을 기반으로 결정적인 버전 업그레이드를 제공합니다.","es":"Habilita flujos de trabajo de evaluación automatizados de código con verificación de ramas, ejecución de pruebas paralelas y gestión de registros de cambios. Proporciona un aumento de versión determinista basado en patrones de versión semántica en la documentación.","fr":"Permet des flux de travail d''évaluation automatiques de code avec vérification de branches, exécution de tests parallèles et gestion des journaux des modifications. Fournit une augmentation de version déterministe basée sur des modèles de version sémantique dans la documentation.","de":"Ermöglicht automatisierte Code-First-Evaluierungs-Workflows mit Branch-Verifizierung, paralleler Testausführung und Changelog-Verwaltung. Bietet deterministisches Version-Bumping basierend auf semantischen Versionierungsmustern in der Dokumentation.","pt":"Habilita fluxos de trabalho de avaliação de código automatizados com verificação de branch, execução de teste paralela e gerenciamento de histórico de alterações. Fornece aumento de versão determinístico com base em padrões de versionamento semântico na documentação.","ru":"Позволяет автоматизировать рабочие процессы оценки кода с проверкой ветки, параллельным выполнением тестов и управлением журналом изменений. Обеспечивает детерминированное увеличение версии на основе семантических шаблонов версионирования в документации.","ar":"يتمكّن من سير عمل التقييم التلقائي للكود مع التحقق من الفرع والتشغيل الموازي للاختبارات وإدارة سجل التعديلات. يوفر زيادة إصدار محددة بناءً على أنماط الإصدار الدلالية في المستندات."},"useCases":{"en":["Automating pre-release validation checks","Executing parallel test suites with pytest","Managing semantic versioning in changelog files"],"zh":["自动执行预发布验证检查","使用 pytest 执行并行测试套件","在更改日志文件中管理语义版本"],"ja":["プレリリースの検証チェックを自動実行する","pytest を使用して並列テスト スイートを実行する","変更ログ ファイル内のセマンティック バージョニングを管理する"],"ko":["프리 릴리스 유효성 검사检查을 자동으로 실행","pytest를 사용하여 병렬 테스트 세트를 실행","변경 로그 파일의 의미 버전 관리"],"es":["Automatizar las comprobaciones de validación previa al lanzamiento","Ejecutar suites de pruebas paralelas con pytest","Gestionar la versión semántica en archivos de changelog"],"fr":["Automatiser les vérifications de validation préalables à la publication","Exécuter des suites de tests parallèles avec pytest","Gérer la version sémantique dans les fichiers de journal des modifications"],"de":["Automatisieren von Vorab-Validierungsprüfungen","Ausführen von parallelen Test-Suiten mit pytest","Verwalten der semantischen Versionierung in Changelog-Dateien"],"pt":["Automatizar verificações de validação pré-lançamento","Executar conjuntos de testes paralelos com pytest","Gerenciar versionamento semântico em arquivos de histórico de alterações"],"ru":["Автоматизировать проверки валидации до выпуска","Выполнять параллельные наборы тестов с pytest","Управлять семантическим версионированием в файлах журнала изменений"],"ar":["توفير عمليات التحقق من الصحة قبل الإصدار","تشغيل مجموعات الاختبارات الموازية مع pytest","إدارة الإصدار الدلالي في ملفات سجل التعديلات"]},"limitations":{"en":["Requires dev branch existence","Depends on test suite completion","Needs structured changelog.mdx format"],"zh":["需要开发分支的存在","依赖于测试套件的完成","需要结构化的 changelog.mdx 格式"],"ja":["開発ブランチの存在が必要","テスト スイートの完了に依存","構造化された changelog.mdx 形式が必要"],"ko":["개발 분기 존재가 필요","테스트 세트 완료에 의존","구조화된 changelog.mdx 형식이 필요"],"es":["Requiere la existencia de una rama de desarrollo","Depende de la finalización de la suite de pruebas","Necesita un formato de changelog.mdx estructurado"],"fr":["Nécessite l''existence d''une branche de développement","Dépend de l''achèvement de la suite de tests","Nécessite un format de changelog.mdx structuré"],"de":["Benötigt die Existenz eines Entwicklungszweigs","Hängt von der Fertigstellung der Test-Suite ab","Benötigt ein strukturiertes Changelog.mdx-Format"],"pt":["Requer a existência de uma branch de desenvolvimento","Depende da conclusão do conjunto de testes","Necessita de formato de arquivo changelog.mdx estruturado"],"ru":["Требует существования ветки разработки","Зависит от завершения набора тестов","Требует структурированного формата файла changelog.mdx"],"ar":["يتطلب وجود فرع تطوير","يعتمد على إكمال مجموعة الاختبارات","يحتاج إلى تنسيق ملف changelog.mdx منظم"]},"version":3},"qualityScore":30}');
