INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Spagestic/thenorthstar/remotion-best-practices', 'community', 'Spagestic', 'thenorthstar', 'Spagestic/thenorthstar', 'remotion-best-practices', 0, 0, 55, '2026-02-18T01:08:43.421Z', '2026-02-18T04:29:13.756Z', NULL, '{"id":"Spagestic/thenorthstar/remotion-best-practices","name":"remotion-best-practices","description":{"zh":"Remotion 最佳实践提供了有关如何使用 Remotion 的指导，包括 3D 内容、动画和资产导入","ja":"Remotion ベストプラクティスでは、Remotion の使用方法に関するガイダンスを提供します。3D コンテンツ、動画、資産のインポートなど","ko":"Remotion 최선의 방법은 Remotion을 사용하는 방법에 대한 지침을 제공합니다. 3D 컨텐츠, 애니메이션 및 자산 가져오기 등","es":"Remotion es una plataforma que permite a los desarrolladores crear experiencias de usuario innovadoras. Aprende las mejores prácticas para dominar Remotion","fr":"Remotion est une plateforme qui permet aux développeurs de créer des expériences utilisateur innovantes. Découvrez les bonnes pratiques pour maîtriser Remotion","de":"Remotion ist eine Plattform, die es Entwicklern ermöglicht, innovative Benutzererfahrungen zu schaffen. Erfahren Sie die Best-Practices, um Remotion zu meistern","pt":"Melhores práticas para trabalhar com Remotion, incluindo dicas para 3D, animações e importação de ativos","ru":"Лучшие практики для работы с Remotion, включая советы по 3D, анимациям и импорту активов","ar":"أفضل الممارسات للعمل مع Remotion، بما في ذلك نصائح حول 3D والرسوم المتحركة واستيراد الأصول","en":"NorthStar is a voice-based GenAI role-play platform that lets students practice realistic job interviews and receive automated, targeted feedback, accelerating communication skills and career readiness for today’s fast-changing market"},"seo":{"title":{"zh":"Remotion 最佳实践","ja":"Remotion ベストプラクティス","ko":"Remotion 최선의 방법","es":"Mejores prácticas de Remotion para desarrolladores","fr":"Bonnes pratiques de Remotion pour les développeurs","de":"Remotion-Best-Practices für Entwickler