INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Rudra370/s3manager/s3manager-git-workflow', 'community', 'Rudra370', 's3manager', 'Rudra370/s3manager', 's3manager-git-workflow', 0, 0, 45, '2026-02-18T01:08:43.425Z', '2026-02-18T04:48:22.913Z', NULL, '{"id":"Rudra370/s3manager/s3manager-git-workflow","name":"s3manager-git-workflow","description":{"zh":"S3 Manager Git工作流是一个自托管的Web界面，用于管理S3兼容存储，优化开发流程","ja":"S3マネージャーギットワークフローは、S3互換ストレージを管理するためのセルフホストWebインターフェースです","ko":"S3 스토리지 관리를 위한 셀프호스팅 웹 인터페이스인 S3 스토리지 관리 Git 워크플로","es":"S3 Manager Git Workflow es una interfaz web autohospedada para gestionar el almacenamiento compatible con S3. Proporciona reglas críticas para cambios de código","fr":"S3 Manager Git Workflow est une interface web auto-hébergée pour gérer le stockage compatible S3. Il fournit des règles critiques pour les modifications de code","de":"S3-Manager-Git-Workflow ist eine selbstgehostete Web-Oberfläche zur Verwaltung von S3-kompatiblen Speicher. Bietet kritische Regeln für Codeänderungen","pt":"O S3 Manager Git Workflow é uma interface de gerenciamento self-hosted para armazenamento S3. Ele fornece regras críticas para gerenciar código","ru":"S3 Менеджер Git Workflow - это веб-интерфейс для управления хранилищем S3. Он предоставляет критические правила для управления кодом","ar":"س3 مانجر جيت ووركفلو هو واجهة إدارة ذاتية الاستضافة لمخزن S3. إنه يوفر قواعد حرجة لإدارة الكود","en":"A beautiful, self-hosted web interface for managing your S3-compatible storage."},"seo":{"title":{"zh":"S3存储管理Git工作流","ja":"S3マネージャーギットワークフロー","ko":"S3 스토리지 관리 Git 워크플로","es":"Flujo de trabajo de S3 Manager Git","fr":"Workflow Git S3 Manager","de":"S3-Manager-Git-Workflow","pt":"S3 Manager Git Workflow: Interface de Gerenciamento","ru":"S3 Менеджер Git Workflow: Веб-интерфейс","ar":"س3 مانجر جيت ووركفلو: واجهة إدارة","en":"s3manager-git-workflow"},"description":{"zh":"S3 Manager Git工作流是一个自托管的Web界面，用于管理S3兼容存储，优化开发流程","ja":"S3マネージャーギットワークフローは、S3互換ストレージを管理するためのセルフホストWebインターフェースです","ko":"S3 스토리지 관리를 위한 셀프호스팅 웹 인터페이스인 S3 스토리지 관리 Git 워크플로","es":"S3 Manager Git Workflow es una interfaz web autohospedada para gestionar el almacenamiento compatible con S3. Proporciona reglas críticas para cambios de código","fr":"S3 Manager Git Workflow est une interface web auto-hébergée pour gérer le stockage compatible S3. Il fournit des règles critiques pour les modifications de code","de":"S3-Manager-Git-Workflow ist eine selbstgehostete Web-Oberfläche zur Verwaltung von S3-kompatiblen Speicher. Bietet kritische Regeln für Codeänderungen","pt":"O S3 Manager Git Workflow é uma interface de gerenciamento self-hosted para armazenamento S3. Ele fornece regras críticas para gerenciar código","ru":"S3 Менеджер Git Workflow - это веб-интерфейс для управления хранилищем S3. Он предоставляет критические правила для управления кодом","ar":"س3 مانجر جيت ووركفلو هو واجهة إدارة ذاتية الاستضافة لمخزن S3. إنه يوفر قواعد حرجة لإدارة الكود","en":"A beautiful, self-hosted web interface for managing your S3-compatible storage."},"definition":{"en":"A beautiful, self-hosted web interface for managing your S3-compatible storage."},"features":{"zh":["基于Git的工作流管理","S3兼容存储管理","自托管Web界面","CRITICAL规则确保代码安全","优化开发流程"],"ja":["Gitベースのワークフローマネジメント","S3互換ストレージ管理","セルフホストWebインターフェース","CRITICALルールによるコードセキュリティ","開発プロセスの最適化"],"ko":["Git 기반 워크플로우 관리","S3 호환 스토리지 관리","셀프호스팅 웹 인터페이스","CRITICAL 규칙에 의한 코드 보안","개발 프로세스 최적화"],"es":["Interfaz web autohospedada","Reglas críticas para cambios de código","Ramificación y fusión de código","Gestión de almacenamiento compatible con S3","Flujo de trabajo de Git para desarrollo"],"fr":["Interface web auto-hébergée","Règles critiques pour les modifications de code","Branche et fusion de code","Gestion de stockage compatible S3","Workflow Git pour le développement"],"de":["Selbstgehostete Web-Oberfläche","Kritische Regeln für Codeänderungen","Code-Branching und -Merging","Verwaltung von S3-kompatiblen Speicher","Git-Workflow für die Entwicklung"],"pt":["Interface de gerenciamento self-hosted","Regras críticas para gerenciar código","Trabalho em branch ''dev''","Proibição de commit direto em ''main''","Proibição de criar branches a partir de ''main''","Proibição de mesclar em ''main''"],"ru":["Веб-интерфейс с自остоятельным хостингом","Критические правила для управления кодом","Работа в ветке ''dev''","Запрет прямого коммита в ''main''","Запрет создания веток из ''main''","Запрет слияния в ''main''"],"ar":["واجهة إدارة ذاتية الاستضافة","قواعد حرجة لإدارة الكود","العمل على فرع ''dev''","منع الالتزام المباشر في ''main''","منع إنشاء فروع من ''main''","منع الدمج في ''main''"]},"keywords":{"zh":["S3存储管理","Git工作流","自托管Web界面","代码安全","开发流程优化","S3兼容存储"],"ja":["S3ストレージ管理","Gitワークフロー","セルフホストWebインターフェース","コードセキュリティ","開発プロセスの最適化","S3互換ストレージ"],"ko":["S3 스토리지 관리","Git 워크플로","셀프호스팅 웹 인터페이스","코드 보안","개발 프로세스 최적화","S3 호환 스토리지"],"es":["S3 Manager Git Workflow","gestión de almacenamiento compatible con S3","reglas críticas para cambios de código","desarrollo de software","Git workflow","interfaz web autohospedada"],"fr":["S3 Manager Git Workflow","gestion de stockage compatible S3","règles critiques pour les modifications de code","développement de logiciels","workflow Git","interface web auto-hébergée"],"de":["S3-Manager-Git-Workflow","Verwaltung von S3-kompatiblen Speicher","kritische Regeln für Codeänderungen","Software-Entwicklung","Git-Workflow","selbstgehostete Web-Oberfläche"],"pt":["S3 Manager Git Workflow","gerenciamento de armazenamento S3","interface de gerenciamento self-hosted","regras críticas para gerenciar código","trabalho em branch ''dev''","desenvolvimento de software","gerenciamento de código"],"ru":["S3 Менеджер Git Workflow","управление хранилищем S3","веб-интерфейс с自остоятельным хостингом","критические правила для управления кодом","работа в ветке ''dev''","разработка программного обеспечения","управление кодом"],"ar":["س3 مانجر جيت ووركفلو","إدارة مخزن S3","واجهة إدارة ذاتية الاستضافة","قواعد حرجة لإدارة الكود","العمل على فرع ''dev''","تطوير البرمجيات","إدارة الكود"]}},"owner":"Rudra370","repo":"s3manager","repoPath":"Rudra370/s3manager","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.425Z","topics":[],"category":"community","skillMd":{"name":"s3manager-git-workflow","description":"MANDATORY git workflow for S3 Manager project. Triggers when asked to implement features, fix bugs, refactor code, make changes, or write tests. ENFORCES critical rules that must NEVER be violated.","bodyPreview":"# S3 Manager Git Workflow\n\nThis skill contains CRITICAL rules that MUST be followed for any code changes to the S3 Manager project.\n\n## ⚠️ CRITICAL RULES - NEVER VIOLATE\n\n### Rule 1: ALWAYS Work on `dev` Branch\n```bash\n# Before making ANY code changes, run:\ngit checkout dev\n\n# If dev doesn''t exist:\ngit checkout -b dev\n```\n- **NEVER** commit directly to `main`\n- **NEVER** create branches from `main`\n- **NEVER** merge to `main` — the user handles this manually\n\n### Rule 2: NEVER Commit Without Exp","body":"# S3 Manager Git Workflow\n\nThis skill contains CRITICAL rules that MUST be followed for any code changes to the S3 Manager project.\n\n## ⚠️ CRITICAL RULES - NEVER VIOLATE\n\n### Rule 1: ALWAYS Work on `dev` Branch\n```bash\n# Before making ANY code changes, run:\ngit checkout dev\n\n# If dev doesn''t exist:\ngit checkout -b dev\n```\n- **NEVER** commit directly to `main`\n- **NEVER** create branches from `main`\n- **NEVER** merge to `main` — the user handles this manually\n\n### Rule 2: NEVER Commit Without Explicit Permission\n- **ALWAYS ask**: \"Should I commit these changes?\"\n- Wait for explicit \"yes\" or \"commit them\" before running `git commit`\n- Do NOT use `git add -f` for gitignored files\n- The user handles commits and pushes\n\n### Rule 3: E2E Test-First Workflow (MANDATORY)\nFor ANY new feature or bug fix:\n\n1. **Write E2E test FIRST** — before touching implementation code\n   - Tests are in `/e2e/test_runner.py`\n   - Add test method to `S3ManagerE2ETests` class\n\n2. **Run test (expect failure)**\n   ```bash\n   cd /root/code/s3manager/e2e && python3 test_runner.py\n   ```\n\n3. **Implement the fix/feature**\n\n4. **Run test again (expect success)**\n   ```bash\n   cd /root/code/s3manager/e2e && python3 test_runner.py\n   ```\n\n5. **Ask permission to commit**\n\n## Workflow Checklist\n\nBefore starting any code change:\n- [ ] `git checkout dev` — on dev branch\n- [ ] Write E2E test first (if feature/fix)\n- [ ] Run test — confirm it fails\n- [ ] Implement change\n- [ ] Run test — confirm it passes\n- [ ] Ask user: \"Should I commit these changes?\"\n\n## Trigger Phrases\n\nThis skill activates when user says things like:\n- \"Fix this bug\"\n- \"Implement feature X\"\n- \"Add Y functionality\"\n- \"Refactor Z\"\n- \"Write a test for...\"\n- \"Update the code to...\"\n- Any request involving code changes\n\n## Quick Commands\n\n```bash\n# Check current branch\ngit branch --show-current\n\n# Checkout dev (or create if missing)\ngit checkout dev 2>/dev/null || git checkout -b dev\n\n# Run E2E tests\ncd /root/code/s3manager/e2e && python3 test_runner.py\n\n# Run fast E2E tests (truncate DB, ~10s faster)\nmake test-fast\n```\n\n## Project Context\n\n- **Backend**: FastAPI + SQLAlchemy + PostgreSQL\n- **Frontend**: React + Material-UI + Vite\n- **Tests**: Playwright E2E tests in `/e2e/`\n- **Default S3**: MinIO (no AWS credentials needed for testing)\n- **Working directory**: `/root/code/s3manager`\n\n## Reminder\n\n**STOP and CHECK**: Am I on `dev` branch? Have I asked permission before committing?\n\nIf the user explicitly says \"commit this\" or \"commit these changes\" — then commit. Otherwise, ask first.\n"},"lastSynced":"2026-02-18T04:48:22.913Z","agentAnalysis":{"suitability":{"en":"Perfect for Version Control Agents needing standardized Git workflows for S3-compatible storage management.","zh":"非常适合需要标准化Git工作流程的版本控制代理，用于管理S3兼容存储。","ja":"S3互換ストレージ管理のための標準化されたGitワークフローを必要とするバージョン管理エージェントに最適。","ko":"S3 호환 스토리지 관리를 위한 표준화된 Git 워크플로가 필요한 버전 관리 에이전트에 적합합니다.","es":"Perfecto para agentes de control de versiones que necesitan flujos de trabajo de Git estandarizados para la gestión de almacenamiento compatible con S3.","fr":"Parfait pour les agents de contrôle de version ayant besoin de flux de travail Git standardisés pour la gestion de stockage compatible S3.","de":"Perfekt für Version Control Agents, die standardisierte Git-Workflows für die Verwaltung von S3-kompatiblen Speicher benötigen.","pt":"Perfeito para agentes de controle de versão que necessitam de fluxos de trabalho Git padronizados para gerenciamento de armazenamento compatível com S3.","ru":"Идеально подходит для агентов контроля версий, требующих стандартизированных рабочих процессов Git для управления хранилищем, совместимым с S3.","ar":"مثالي للوكلاء إدارة الإصدارات الذين يحتاجون إلى سير عمل Git معيارية لإدارة تخزين متوافق مع S3."},"recommendation":{"en":"Empowers agents to enforce critical Git rules, such as always working on the ''dev'' branch and never committing without proper review, ensuring seamless S3 manager project maintenance using Git protocols.","zh":"赋予代理人执行关键的Git规则的能力，例如始终在''dev''分支上工作，确保使用Git协议进行无缝的S3管理项目维护，且不允许在未经适当审查的情况下提交。","ja":"エージェントが重要なGitルールを適用できるようにし、常に''dev''ブランチで作業し、適切なレビューなしにコミットしないことを保証し、Gitプロトコルを使用してS3マネージャープロジェクトのメンテナンスをスムーズに行う。","ko":"에이전트가 중요한 Git 규칙을 적용할 수 있도록 하여 ''dev'' 분기에서 항상 작업하고 적절한 검토 없이 커밋하지 않도록 하여 Git 프로토콜을 사용하여 S3 관리자 프로젝트 유지 관리를 무중단으로 진행합니다.","es":"Habilita a los agentes a aplicar reglas Git críticas, como siempre trabajar en la rama ''dev'' y nunca confirmar sin una revisión adecuada, garantizando un mantenimiento sin problemas del proyecto de gestor de S3 mediante protocolos Git.","fr":"Permet aux agents d''appliquer des règles Git critiques, telles que travailler toujours sur la branche ''dev'' et ne jamais valider sans examen approprié, assurant ainsi une maintenance sans problème du projet de gestionnaire S3 à l''aide de protocoles Git.","de":"Ermächtigt Agenten, kritische Git-Regeln durchzusetzen, wie z. B. immer in der ''dev''-Zweig zu arbeiten und niemals ohne ordnungsgemäße Überprüfung zu committen, um so eine nahtlose Wartung von S3-Manager-Projekten unter Verwendung von Git-Protokollen sicherzustellen.","pt":"Habilita os agentes a impor regras Git críticas, como sempre trabalhar no branch ''dev'' e nunca comprometer sem revisão adequada, garantindo a manutenção sem problemas do projeto do gerenciador S3 usando protocolos Git.","ru":"Наделяет агентов возможностью обеспечивать соблюдение критически важных правил Git, таких как всегда работа в ветке ''dev'' и никогда не фиксировать без надлежащего рассмотрения, обеспечивая бесперебойное обслуживание проекта менеджера S3 с использованием протоколов Git.","ar":"تمكّن الوكلاء من فرض قواعد Git الحاسمة، مثل العمل دائمًا على الفروع ''dev'' وعدم الالتزام بدون مراجعة مناسبة، مما يضمن صيانة مشروع مدير S3 بدون مشاكل باستخدام بروتوكولات Git."},"useCases":{"en":["Enforcing Git workflow standards for S3 storage","Automating branch management for S3-compatible projects","Validating commit history for S3 manager projects"],"zh":["执行S3存储的Git工作流标准","自动化S3兼容项目的分支管理","验证S3管理项目的提交历史"],"ja":["S3ストレージのGitワークフローの標準を適用する","S3互換プロジェクトのブランチ管理を自動化する","S3マネージャープロジェクトのコミット履歴を検証する"],"ko":["S3 스토리지의 Git 워크플로우 표준 적용","S3 호환 프로젝트의 분기 관리 자동화","S3 관리자 프로젝트의 커밋 기록 검증"],"es":["Aplicar normas de flujo de trabajo de Git para el almacenamiento de S3","Automatizar la gestión de ramas para proyectos compatibles con S3","Validar el historial de confirmaciones para los proyectos del gestor de S3"],"fr":["Appliquer des normes de flux de travail Git pour le stockage S3","Automatiser la gestion des branches pour les projets compatibles S3","Valider l''historique des validations pour les projets de gestionnaire S3"],"de":["Git-Workflow-Standards für die S3-Speicherung durchsetzen","Automatisierung der Verwaltung von Zweigen für S3-kompatible Projekte","Validierung der Commit-Historie für S3-Manager-Projekte"],"pt":["Impor padrões de fluxo de trabalho Git para armazenamento S3","Automatizar gerenciamento de branch para projetos compatíveis com S3","Validar histórico de comprometimento para projetos do gerenciador S3"],"ru":["Обеспечение стандартов рабочих процессов Git для хранилища S3","Автоматизация управления ветками для проектов, совместимых с S3","Проверка истории фиксации для проектов менеджера S3"],"ar":["فرض معايير سير عمل Git لتخزين S3","توسيط إدارة الفروع للمشاريع المتوافقة مع S3","التحقق من سجل الالتزام لمشاريع مدير S3"]},"limitations":{"en":["Requires Git version control system","Manual merge to ''main'' branch required","Adherence to specific branch naming conventions (e.g., ''dev'', ''main'')"],"zh":["需要Git版本控制系统","需要手动合并到''main''分支","需要遵守特定的分支命名约定（例如，''dev''，''main''）"],"ja":["Gitバージョン管理システムが必要","''main''ブランチへのマージは手動で行う必要がある","特定のブランチ命名規則（例：''dev''、''main''）に従う必要がある"],"ko":["Git 버전 관리 시스템이 필요합니다.","''main'' 분기에 대한 병합은 수동으로 수행해야 합니다.","특정 분기 이름 규칙(''dev'', ''main'' 등)을 따라야 합니다."],"es":["Requiere sistema de control de versiones Git","Se requiere una fusión manual en la rama ''main''","Adhesión a convenciones de nomenclatura de ramas específicas (por ejemplo, ''dev'', ''main'')"],"fr":["Nécessite un système de contrôle de version Git","Une fusion manuelle dans la branche ''main'' est requise","Adhésion à des conventions de nommage de branche spécifiques (par exemple, ''dev'', ''main'')"],"de":["Benötigt Git-Version-Control-System","Manuelle Zusammenführung in den ''main''-Zweig erforderlich","Einhaltung spezifischer Branch-Benennungskonventionen (z. B. ''dev'', ''main'')"],"pt":["Requer sistema de controle de versão Git","Mesclagem manual para branch ''main'' necessária","Adesão a convenções de nomenclatura de branch específicas (por exemplo, ''dev'', ''main'')"],"ru":["Требуется система контроля версий Git","Требуется ручной мердж в ветку ''main''","Соблюдение конкретных соглашений о наименовании веток (например, ''dev'', ''main'')"],"ar":["يتطلب نظام إدارة الإصدارات Git","التحام اليدوي للفرع ''main'' مطلوب","الامتثال لاتفاقيات تسمية الفروع النوعية (على سبيل المثال ''dev'' و ''main'')"]},"version":3},"qualityScore":45}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('raudyagdel/ai_setup_and_tips/angular-development', 'community', 'raudyagdel', 'ai_setup_and_tips', 'raudyagdel/ai_setup_and_tips', 'angular-development', 0, 0, 0, '2026-02-18T01:08:43.425Z', '2026-02-18T04:49:08.105Z', NULL, '{"id":"raudyagdel/ai_setup_and_tips/angular-development","name":"angular-development","description":{"zh":"Angular开发专家指南，涵盖类型安全、组件组合和性能优化等关键原则","ja":"Angular開発のエキスパートガイド：型の安全性、コンポーネントの構成、パフォーマンスの最適化","ko":"Angular 개발을 위한 전문가 가이드: 타입 안전성, 컴포넌트 구성, 성능 최적화","es":"Desarrollo Angular con enfoque en escalabilidad y alto rendimiento. Principios de tipo seguro y composición de componentes","fr":"Développement Angular avec un focus sur la scalabilité et les hautes performances. Principes de sécurité de type et composition de composants","de":"Angular-Entwicklung mit Fokus auf Skalierbarkeit und Hochleistung. Prinzipien der Typsicherheit und Komponentenkomposition","en":"AI Setup MarkDown For Copilot, Claude, Codex And Gemini"},"seo":{"title":{"zh":"Angular开发最佳实践","ja":"Angular開発のベストプラクティス","ko":"Angular 개발 가이드","es":"Desarrollo Angular: Mejores Prácticas y Principios","fr":"Développement Angular: Meilleures Pratiques et Principes","de":"Angular-Entwicklung: Beste Praktiken und Prinzipien","en":"angular-development"},"description":{"zh":"Angular开发专家指南，涵盖类型安全、组件组合和性能优化等关键原则","ja":"Angular開発のエキスパートガイド：型の安全性、コンポーネントの構成、パフォーマンスの最適化","ko":"Angular 개발을 위한 전문가 가이드: 타입 안전성, 컴포넌트 구성, 성능 최적화","es":"Desarrollo Angular con enfoque en escalabilidad y alto rendimiento. Principios de tipo seguro y composición de componentes","fr":"Développement Angular avec un focus sur la scalabilité et les hautes performances. Principes de sécurité de type et composition de composants","de":"Angular-Entwicklung mit Fokus auf Skalierbarkeit und Hochleistung. Prinzipien der Typsicherheit und Komponentenkomposition","en":"AI Setup MarkDown For Copilot, Claude, Codex And Gemini"},"definition":{"en":"AI Setup MarkDown For Copilot, Claude, Codex And Gemini"},"features":{"zh":["类型安全性","组件组合","性能优化","模块化设计","可扩展性"],"ja":["型の安全性","コンポーネントの構成","パフォーマンスの最適化","モジュール化設計","スケーラビリティ"],"ko":["타입 안전성","컴포넌트 구성","성능 최적화","모듈화 설계","확장 가능성"],"es":["Tipos seguros con interfaces","Composición de componentes","Escalabilidad y alto rendimiento","Uso de TypeScript y SASS","Principios de desarrollo modulares"],"fr":["Sécurité de type avec des interfaces","Composition de composants","Évolutivité et hautes performances","Utilisation de TypeScript et SASS","Principes de développement modulaires"],"de":["Typsicherheit mit Schnittstellen","Komponentenkomposition","Skalierbarkeit und Hochleistung","Verwendung von TypeScript und SASS","Modulare Entwicklungsprinzipien"]},"keywords":{"zh":["Angular开发","类型安全","组件组合","性能优化","模块化设计","可扩展性","Web应用开发"],"ja":["Angular開発","型の安全性","コンポーネントの構成","パフォーマンスの最適化","モジュール化設計","スケーラビリティ","Webアプリケーション開発"],"ko":["Angular 개발","타입 안전성","컴포넌트 구성","성능 최적화","모듈화 설계","확장 가능성","웹 애플리케이션 개발"],"es":["desarrollo angular","angular js","typescript","sass","escalabilidad","alto rendimiento","principios de desarrollo","componentes","interfaces"],"fr":["développement angular","angular js","typescript","sass","évolutivité","hautes performances","principes de développement","composants","interfaces"],"de":["angular-entwicklung","angular js","typescript","sass","skalierbarkeit","hochleistung","entwicklungsprinzipien","komponenten","schnittstellen"]}},"owner":"raudyagdel","repo":"ai_setup_and_tips","repoPath":"raudyagdel/ai_setup_and_tips","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.425Z","topics":[],"category":"community","skillMd":{"name":"angular-development","description":"Expert guidance for Angular and TypeScript development focused on scalable, high-performance web applications","bodyPreview":"# Angular Development\n\nYou are an Angular, SASS, and TypeScript expert focused on creating scalable and high-performance web applications.\n\n## Key Development Principles\n\n### Type Safety with Interfaces\n- Define data models using interfaces for explicit types\n- Maintain strict typing to avoid `any`\n- Use TypeScript''s type system to define specific types\n\n### Component Composition\n- Favor component composition over inheritance\n- Enhance modularity, enabling reusability and easy maintenance\n\n### M","body":"# Angular Development\n\nYou are an Angular, SASS, and TypeScript expert focused on creating scalable and high-performance web applications.\n\n## Key Development Principles\n\n### Type Safety with Interfaces\n- Define data models using interfaces for explicit types\n- Maintain strict typing to avoid `any`\n- Use TypeScript''s type system to define specific types\n\n### Component Composition\n- Favor component composition over inheritance\n- Enhance modularity, enabling reusability and easy maintenance\n\n### Meaningful Naming\n- Use descriptive variable names like `isUserLoggedIn`, `userPermissions`\n- Communicate intent clearly through naming\n\n### File Naming\n- Enforce kebab-case naming for files (e.g., `user-profile.component.ts`)\n- Match Angular''s conventions for file suffixes\n\n## Angular Best Practices\n\n### Standalone Components\n- Use standalone components as appropriate\n- Promote code reusability without relying on Angular modules\n\n### Signals for State Management\n- Utilize Angular''s signals system for efficient reactive programming\n- Enhance both state handling and rendering performance\n\n### Service Injection\n- Use the `inject` function to inject services directly\n- Reduce boilerplate code\n\n### Template Best Practices\n- Use `async` pipe for observables in templates\n- Enable lazy loading for feature modules\n- Use `NgOptimizedImage` for efficient image loading\n- Implement deferrable views for non-essential components\n\n## File Structure\n\n- **Component Files**: `*.component.ts`\n- **Service Files**: `*.service.ts`\n- **Module Files**: `*.module.ts`\n- **Directive Files**: `*.directive.ts`\n- **Pipe Files**: `*.pipe.ts`\n- **Test Files**: `*.spec.ts`\n\n## Coding Standards\n\n- Use single quotes for string literals\n- Use 2-space indentation\n- Prefer `const` for constants and immutable variables\n- Use template literals for string interpolation\n\n## Performance Optimization\n\n- Use trackBy functions with `ngFor` to optimize list rendering\n- Apply pure pipes for computationally heavy operations\n- Avoid direct DOM manipulation\n- Leverage Angular''s signals system to reduce unnecessary re-renders\n\n## Security Best Practices\n\n- Prevent XSS by relying on Angular''s built-in sanitization\n- Avoid `innerHTML`\n- Sanitize dynamic content using Angular''s trusted sanitization methods\n\n## Testing\n\n- Adhere to the Arrange-Act-Assert pattern for unit tests\n- Ensure high test coverage for services, components, and utilities\n"},"lastSynced":"2026-02-18T04:49:08.105Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring scalable and high-performance Angular web application development with TypeScript and SASS expertise.","zh":"適合需要擴展性高和高性能的Angular網頁應用程式開發的前端代理，同時需要TypeScript和SASS的專業知識。","ja":"スケーラブルで高性能なAngular Webアプリケーション開発を必要とするフロントエンドエージェントに適しています。TypeScriptとSASSの専門知識が必要です。","ko":"확장성과 고성능을 필요로 하는 Angular 웹 애플리케이션 개발을 위한 프론트엔드 에이전트에게 적합합니다. TypeScript와 SASS에 대한 전문 지식이 필요합니다.","es":"Ideal para agentes Frontend que requieren un desarrollo de aplicaciones web Angular escalable y de alto rendimiento con experiencia en TypeScript y SASS.","fr":"Idéal pour les agents Frontend nécessitant un développement d''applications web Angular évolutif et haute performance avec une expertise en TypeScript et SASS.","de":"Ideal für Frontend-Agents, die eine skalierbare und hochleistungsstarke Angular-Webanwendungsentwicklung mit TypeScript- und SASS-Expertise erfordern.","pt":"Ideal para Agentes Frontend que requerem desenvolvimento de aplicações web escaláveis e de alto desempenho com Angular, TypeScript e especialização em SASS.","ru":"Идеально для Фронтенд-агентов, требующих масштабируемого и высокопроизводительного разработки веб-приложений Angular с помощью TypeScript и экспертизы SASS.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذين يحتاجون إلى تطوير تطبيقات ويب قابلة للتحجيم وعالية الأداء باستخدام Angular و TypeScript وخبرة SASS."},"recommendation":{"en":"Empowers agents to create modular and reusable components using component composition, while maintaining strict type safety with TypeScript interfaces and avoiding implicit ''any'' types, thus enhancing code quality and maintainability with SASS for styling.","zh":"賦予代理人使用組件組合創建模塊化和可重用組件的能力，同時使用TypeScript接口維持嚴格的類型安全，避免隱式的任何類型，從而提高代碼質量和可維護性，並使用SASS進行樣式設定。","ja":"エージェントに、コンポーネントの組み合わせを使用してモジュール化および再利用可能なコンポーネントを作成する機能を提供します。TypeScriptのインターフェースを使用して厳格な型の安全性を維持し、暗黙のany型を回避して、コードの品質と保守性を高め、SASSを使用してスタイリングします。","ko":"에이전트가 컴포넌트 조합을 사용하여 모듈화되고 재사용 가능한 컴포넌트를 생성할 수 있는 기능을 제공합니다. TypeScript 인터페이스를 사용하여 엄격한 유형 안전성을 유지하고, 암시적인 any 유형을 피하여, 코드 품질과 유지 보수성을 향상시키고, SASS를 사용하여 스타일링합니다.","es":"Permite a los agentes crear componentes modulares y reutilizables utilizando la composición de componentes, manteniendo al mismo tiempo una estricta seguridad de tipos con interfaces de TypeScript y evitando los tipos ''any'' implícitos, lo que mejora la calidad y mantenibilidad del código con SASS para la estilización.","fr":"Permet aux agents de créer des composants modulaires et réutilisables en utilisant la composition de composants, tout en maintenant une sécurité de type stricte avec les interfaces TypeScript et en évitant les types ''any'' implicites, améliorant ainsi la qualité et la maintenabilité du code avec SASS pour la stylisation.","de":"Ermöglicht es den Agenten, modulare und wiederverwendbare Komponenten unter Verwendung der Komponentenzusammensetzung zu erstellen, während gleichzeitig eine strikte Typsicherheit mit TypeScript-Schnittstellen aufrechterhalten wird und implizite ''any''-Typen vermieden werden, wodurch die Codequalität und Wartbarkeit mit SASS für die Stilgebung verbessert werden.","pt":"Habilita os agentes a criarem componentes modulares e reutilizáveis usando composição de componentes, mantendo ao mesmo tempo uma estrita segurança de tipo com interfaces TypeScript e evitando tipos ''any'' implícitos, melhorando assim a qualidade e manutenção do código com SASS para estilização.","ru":"Наделяет агентов возможностью создавать модульные и повторно используемые компоненты с помощью композиции компонентов, сохраняя при этом строгую безопасность типов с помощью интерфейсов TypeScript и избегая неявных типов ''any'', тем самым повышая качество и поддерживаемость кода с помощью SASS для стилизации.","ar":"يمنح الوكلاء khảية إنشاء مكونات قابلة للتحجيم ويمكن إعادة استخدامها باستخدام تكوين المكونات، مع الحفاظ في الوقت نفسه على سلامة صارمة من النوع باستخدام واجهات برمجة تطبيقات TypeScript وتجنب أنواع ''any'' الضمنية، مما يحسن بذلك جودة وصيانة الشفرة مع SASS للتنسيق."},"useCases":{"en":["Developing scalable Angular applications with strict typing","Creating reusable and modular components with component composition","Implementing type safety using TypeScript interfaces for explicit data models"],"zh":["開發具有嚴格類型的可擴展Angular應用程式","使用組件組合創建可重用和模塊化的組件","使用TypeScript接口實現類型安全以獲得明確的數據模型"],"ja":["厳格な型付けを持つスケーラブルなAngularアプリケーションを開発する","コンポーネントの組み合わせを使用して再利用可能なモジュール化コンポーネントを作成する","TypeScriptのインターフェースを使用して型の安全性を実現し、明示的なデータモデルの取得"],"ko":["严格한 형식 지정이 있는 확장 가능한 Angular 애플리케이션 개발","컴포넌트 조합을 사용하여 재사용 가능한 모듈화된 컴포넌트 생성","TypeScript 인터페이스를 사용하여 유형 안전성을 구현하여 명시적인 데이터 모델을 얻음"],"es":["Desarrollar aplicaciones Angular escalables con tipificación estricta","Crear componentes reutilizables y modulares con composición de componentes","Implementar la seguridad de tipos utilizando interfaces de TypeScript para modelos de datos explícitos"],"fr":["Développer des applications Angular évolutives avec une typification stricte","Créer des composants réutilisables et modulaires avec la composition de composants","Mettre en œuvre la sécurité de type en utilisant des interfaces TypeScript pour des modèles de données explicites"],"de":["Entwicklung von skalierbaren Angular-Anwendungen mit strenger Typisierung","Erstellung von wiederverwendbaren und modularen Komponenten mit Komponentenzusammensetzung","Implementierung der Typsicherheit unter Verwendung von TypeScript-Schnittstellen für explizite Datenmodelle"],"pt":["Desenvolver aplicações Angular escaláveis com digitação estrita","Criar componentes reutilizáveis e modulares com composição de componentes","Implementar segurança de tipo usando interfaces TypeScript para modelos de dados explícitos"],"ru":["Разрабатывать масштабируемые приложения Angular с строгой типизацией","Создавать повторно используемые и модульные компоненты с помощью композиции компонентов","Реализовывать безопасность типов с помощью интерфейсов TypeScript для явных моделей данных"],"ar":["تطوير تطبيقات Angular قابلة للتحجيم مع كتابة صارمة","إنشاء مكونات قابلة لإعادة الاستخدام وقابلة للتحجيم مع تكوين المكونات","تنفيذ سلامة النوع باستخدام واجهات برمجة تطبيقات TypeScript لنماذج البيانات الصريحة"]},"limitations":{"en":["Requires knowledge of TypeScript, SASS, and Angular framework","Focused on frontend development only"],"zh":["需要TypeScript、SASS和Angular框架的知識","僅限於前端開發"],"ja":["TypeScript、SASS、Angularフレームワークの知識が必要","フロントエンド開発のみに焦点を当てている"],"ko":["TypeScript, SASS, Angular 프레임워크에 대한 지식이 필요","프론트엔드 개발에만 초점을 둠"],"es":["Requiere conocimiento de TypeScript, SASS y framework Angular","Se centra exclusivamente en el desarrollo frontend"],"fr":["Nécessite des connaissances en TypeScript, SASS et framework Angular","Se concentre uniquement sur le développement frontend"],"de":["Benötigt Kenntnisse in TypeScript, SASS und Angular-Framework","Konzentriert sich ausschließlich auf die Frontend-Entwicklung"],"pt":["Requer conhecimento de TypeScript, SASS e framework Angular","Focado apenas no desenvolvimento frontend"],"ru":["Требует знания TypeScript, SASS и фреймворка Angular","Сосредоточен только на разработке frontend"],"ar":["يتطلب معرفة TypeScript و SASS و إطار العمل Angular","محدود فقط على تطوير واجهة المستخدم الأمامية"]},"version":3},"qualityScore":0}');
