INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blesstosam/trpc-fastify-starter/fastify-best-practices', 'community', 'blesstosam', 'trpc-fastify-starter', 'blesstosam/trpc-fastify-starter', 'fastify-best-practices', 0, 0, 50, '2026-02-18T01:08:43.426Z', '2026-02-18T04:53:40.955Z', NULL, '{"id":"blesstosam/trpc-fastify-starter/fastify-best-practices","name":"fastify-best-practices","description":{"zh":"Fastify 最佳实践提供了开发高性能后端应用的指导，包括插件、路由处理和测试","ja":"Fastify ベストプラクティスは、高性能なバックエンドアプリケーションを開発するためのプラグイン、ルーティングハンドラー、テストに関するガイダンス","ko":"Fastify 최적화 방법은 높은 성능의 백엔드 애플리케이션을 개발하는 방법에 대한 지침을 제공합니다. 플러그인, 라우팅 핸들러 및 테스트","es":"Desarrolla aplicaciones backend con Fastify de manera efectiva. Implementa plugins y controladores de rutas con facilidad.","fr":"Développez des applications backend avec Fastify de manière efficace. Implémentez des plugins et des controlleurs de routes avec facilite.","de":"Entwickeln Sie Backend-Anwendungen mit Fastify effektiv. Implementieren Sie Plugins und Routen-Controller mit Leichtigkeit.","en":""},"seo":{"title":{"zh":"Fastify 最佳实践","ja":"Fastify ベストプラクティス","ko":"Fastify 최적화 방법","es":"Mejores prácticas de Fastify para desarrolladores","fr":"Meilleures pratiques Fastify pour les développeurs","de":"Fastify-Best-Practices für Entwickler","en":"fastify-best-practices"},"description":{"zh":"Fastify 最佳实践提供了开发高性能后端应用的指导，包括插件、路由处理和测试","ja":"Fastify ベストプラクティスは、高性能なバックエンドアプリケーションを開発するためのプラグイン、ルーティングハンドラー、テストに関するガイダンス","ko":"Fastify 최적화 방법은 높은 성능의 백엔드 애플리케이션을 개발하는 방법에 대한 지침을 제공합니다. 플러그인, 라우팅 핸들러 및 테스트","es":"Desarrolla aplicaciones backend con Fastify de manera efectiva. Implementa plugins y controladores de rutas con facilidad.","fr":"Développez des applications backend avec Fastify de manière efficace. Implémentez des plugins et des controlleurs de routes avec facilite.","de":"Entwickeln Sie Backend-Anwendungen mit Fastify effektiv. Implementieren Sie Plugins und Routen-Controller mit Leichtigkeit.","en":""},"definition":{"en":""},"features":{"zh":["Fastify 插件开发","路由处理和架构设计","TypeScript 集成","测试和调试","验证和序列化"],"ja":["Fastify プラグインの開発","ルーティングハンドラーと設計","TypeScript の統合","テストとデバッグ","バリデーションとシリアライズ"],"ko":["Fastify 플러그인 개발","라우팅 핸들러 및 아키텍처 설계","TypeScript 통합","테스트 및 디버깅","검증 및 직렬화"],"es":["Implementación de plugins y controladores de rutas","Arquitectura y patrones de Fastify","Uso de TypeScript con Fastify","Pruebas con el método inject de Fastify","Validación, serialización y manejo de errores"],"fr":["Implémentation de plugins et de controlleurs de routes","Architecture et modèles de Fastify","Utilisation de TypeScript avec Fastify","Tests avec la méthode inject de Fastify","Validation, sérialisation et gestion des erreurs"],"de":["Implementierung von Plugins und Routen-Controllern","Fastify-Architektur und -Muster","Verwendung von TypeScript mit Fastify","Tests mit der inject-Methode von Fastify","Validierung, Serialisierung und Fehlerbehandlung"]},"keywords":{"zh":["Fastify","后端开发","高性能应用","插件开发","TypeScript","测试和调试"],"ja":["Fastify","バックエンド開発","高性能アプリケーション","プラグイン開発","TypeScript","テストとデバッグ"],"ko":["Fastify","백엔드 개발","고성능 애플리케이션","플러그인 개발","TypeScript","테스트 및 디버깅"],"es":["Fastify","desarrollo backend","plugins de Fastify","controladores de rutas","TypeScript con Fastify","pruebas con Fastify","validación y serialización"],"fr":["Fastify","développement backend","plugins Fastify","controlleurs de routes","TypeScript avec Fastify","tests avec Fastify","validation et sérialisation"],"de":["Fastify","Backend-Entwicklung","Fastify-Plugins","Routen-Controller","TypeScript mit Fastify","Tests mit Fastify","Validierung und Serialisierung"]}},"owner":"blesstosam","repo":"trpc-fastify-starter","repoPath":"blesstosam/trpc-fastify-starter","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.426Z","topics":[],"category":"community","skillMd":{"name":"fastify-best-practices","description":"Comprehensive best practices for Fastify development","tags":"fastify, nodejs, typescript, backend, api, server, http","bodyPreview":"## When to use\n\nUse this skill when you need to:\n- Develop backend applications using Fastify\n- Implement Fastify plugins and route handlers\n- Get guidance on Fastify architecture and patterns\n- Use TypeScript with Fastify (strip types)\n- Implement testing with Fastify''s inject method\n- Configure validation, serialization, and error handling\n\n## How to use\n\nRead individual rule files for detailed explanations and code examples:\n\n- [rules/schemas.md](rules/schemas.md) - JSON Schema validation\n- [","body":"## When to use\n\nUse this skill when you need to:\n- Develop backend applications using Fastify\n- Implement Fastify plugins and route handlers\n- Get guidance on Fastify architecture and patterns\n- Use TypeScript with Fastify (strip types)\n- Implement testing with Fastify''s inject method\n- Configure validation, serialization, and error handling\n\n## How to use\n\nRead individual rule files for detailed explanations and code examples:\n\n- [rules/schemas.md](rules/schemas.md) - JSON Schema validation\n- [rules/error-handling.md](rules/error-handling.md) - Error handling patterns\n- [rules/hooks.md](rules/hooks.md) - Hooks and request lifecycle\n- [rules/authentication.md](rules/authentication.md) - Authentication and authorization\n- [rules/testing.md](rules/testing.md) - Testing with inject()\n- [rules/performance.md](rules/performance.md) - Performance optimization\n- [rules/logging.md](rules/logging.md) - Logging with Pino\n- [rules/typescript.md](rules/typescript.md) - TypeScript integration\n- [rules/content-type.md](rules/content-type.md) - Content type parsing\n- [rules/serialization.md](rules/serialization.md) - Response serialization\n- [rules/cors-security.md](rules/cors-security.md) - CORS and security headers\n- [rules/websockets.md](rules/websockets.md) - WebSocket support\n- [rules/configuration.md](rules/configuration.md) - Application configuration\n- [rules/http-proxy.md](rules/http-proxy.md) - HTTP proxying and reply.from()\n\n## Core Principles\n\n- **Encapsulation**: Fastify''s plugin system provides automatic encapsulation\n- **Schema-first**: Define schemas for validation and serialization\n- **Performance**: Fastify is optimized for speed; use its features correctly\n- **Async/await**: All handlers and hooks support async functions\n- **Minimal dependencies**: Prefer Fastify''s built-in features and official plugins\n"},"lastSynced":"2026-02-18T04:53:40.955Z","agentAnalysis":{"suitability":{"en":"Ideal for Node.js Agents seeking to develop high-performance backend applications with Fastify","zh":"适用于 Node.js 代理，旨在使用 Fastify 开发高性能后端应用程序","ja":"Node.js エージェントが Fastify を使用して高パフォーマンスのバックエンドアプリケーションを開発するのに適しています","ko":"Fastify를 사용하여 고성능 백엔드 애플리케이션을 개발하려는 Node.js 에이전트에 적합합니다","es":"Ideal para agentes de Node.js que buscan desarrollar aplicaciones de backend de alto rendimiento con Fastify","fr":"Idéal pour les agents Node.js qui cherchent à développer des applications backend hautes performances avec Fastify","de":"Ideal für Node.js-Agents, die hochleistungsstarke Backend-Anwendungen mit Fastify entwickeln möchten","pt":"Ideal para Agentes Node.js que buscam desenvolver aplicações de backend de alto desempenho com Fastify","ru":"Идеально для агентов Node.js, стремящихся разработать высокопроизводительные приложения бэкенда с Fastify","ar":"مثالي لعميل Node.js الذين يبحثون عن تطوير تطبيقات الخوادم عالية الأداء مع Fastify"},"recommendation":{"en":"Empowers agents to implement robust Fastify plugins, route handlers, and validation using JSON Schema, while also providing guidance on architecture, TypeScript integration, and testing with Fastify''s inject method","zh":"赋予代理实现强大的 Fastify 插件、路由处理程序和使用 JSON 模式的验证，同时还提供有关架构、TypeScript 集成和使用 Fastify 的 inject 方法进行测试的指导","ja":"エージェントが JSON スキーマを使用した堅牢なプラグイン、ルートハンドラー、バリデーションを実装できるようにし、同時にアーキテクチャ、TypeScript 統合、および Fastify の inject メソッドを使用したテストに関するガイダンスを提供します","ko":"에이전트가 JSON 스키마를 사용하여 강력한 플러그인, 라우트 핸들러 및 유효성을 검사할 수 있도록 하며, 아키텍처, TypeScript 통합 및 Fastify의 inject 메서드를 사용한 테스트에 대한 지침을 제공합니다","es":"Habilita a los agentes a implementar plugins de Fastify robustos, controladores de rutas y validación utilizando JSON Schema, y también proporciona orientación sobre arquitectura, integración de TypeScript y pruebas con el método inject de Fastify","fr":"Permet aux agents de mettre en œuvre des plugins Fastify robustes, des gestionnaires de routes et une validation utilisant JSON Schema, et fournit également des conseils sur l''architecture, l''intégration de TypeScript et les tests avec la méthode inject de Fastify","de":"Ermächtigt die Agenten, robuste Fastify-Plugins, Routen-Handler und Validierung unter Verwendung von JSON Schema zu implementieren und bietet auch Anleitung zu Architektur, TypeScript-Integration und Tests mit der inject-Methode von Fastify","pt":"Habilita os agentes a implementar plugins robustos do Fastify, manipuladores de rotas e validação usando JSON Schema, além de fornecer orientação sobre arquitetura, integração do TypeScript e testes com o método inject do Fastify","ru":"Позволяет агентам реализовывать прочные плагины Fastify, обработчики маршрутов и валидацию с использованием JSON Schema, а также предоставляет рекомендации по архитектуре, интеграции TypeScript и тестированию с помощью метода inject Fastify","ar":"يمنح الوكلاء القدرة على تنفيذ إضافات قوية من Fastify ومعالجات المسارات و التحقق من البيانات باستخدام مخطط JSON، بالإضافة إلى تقديم إرشادات حول الهندسة المعمارية وتكامل TypeScript والاختبار باستخدام طريقة الحقن في Fastify"},"useCases":{"en":["Implementing JSON Schema validation for robust data handling","Developing scalable backend applications using Fastify and TypeScript","Configuring efficient error handling and serialization in Fastify","Writing unit tests for Fastify applications using the inject method"],"zh":["实现 JSON 模式验证以进行强大的数据处理","使用 Fastify 和 TypeScript 开发可扩展的后端应用程序","在 Fastify 中配置高效的错误处理和序列化","使用 inject 方法为 Fastify 应用程序编写单元测试"],"ja":["堅牢なデータ処理のための JSON スキーマの検証を実装する","Fastify と TypeScript を使用してスケーラブルなバックエンドアプリケーションを開発する","Fastify で効率的なエラーハンドリングとシリアル化を構成する","inject メソッドを使用して Fastify アプリケーションのユニットテストを書く"],"ko":["강력한 데이터 처리를 위한 JSON 스키마 유효성 검사를 구현하는 것","Fastify와 TypeScript를 사용하여 확장 가능한 백엔드 애플리케이션을 개발하는 것","Fastify에서 효율적인 오류 처리 및 직렬화를 구성하는 것","inject 메서드를 사용하여 Fastify 애플리케이션의 단위 테스트를 작성하는 것"],"es":["Implementación de la validación de JSON Schema para un manejo de datos robusto","Desarrollo de aplicaciones de backend escalables utilizando Fastify y TypeScript","Configuración de un manejo de errores y serialización eficiente en Fastify","Escritura de pruebas unitarias para aplicaciones Fastify utilizando el método inject"],"fr":["Mise en œuvre de la validation de JSON Schema pour une gestion de données robuste","Développement d''applications backend escalables en utilisant Fastify et TypeScript","Configuration d''une gestion d''erreurs et de sérialisation efficace dans Fastify","Écriture de tests unitaires pour les applications Fastify en utilisant la méthode inject"],"de":["Implementierung der JSON-Schema-Validierung für eine robuste Datenverarbeitung","Entwicklung von skalierbaren Backend-Anwendungen unter Verwendung von Fastify und TypeScript","Konfiguration einer effizienten Fehlerbehandlung und Serialisierung in Fastify","Schreiben von Einheitstests für Fastify-Anwendungen unter Verwendung der inject-Methode"],"pt":["Implementação da validação do esquema JSON para manipulação robusta de dados","Desenvolvimento de aplicações de backend escaláveis usando Fastify e TypeScript","Configuração do tratamento eficiente de erros e serialização no Fastify","Escrita de testes unitários para aplicações Fastify usando o método inject"],"ru":["Реализация валидации схемы JSON для прочной обработки данных","Разработка масштабируемых приложений бэкенда с использованием Fastify и TypeScript","Настройка эффективной обработки ошибок и сериализации в Fastify","Написание модульных тестов для приложений Fastify с использованием метода inject"],"ar":["تنفيذ التحقق من مخطط JSON للتعامل القوي مع البيانات","تطوير تطبيقات الخوادم القابلة للتوسيع باستخدام Fastify و TypeScript","تكوين معالجة الأخطاء والتحويل الفعال في Fastify","كتابة الاختبارات الوحدوية للتطبيقات Fastify باستخدام طريقة الحقن"]},"limitations":{"en":["Requires Node.js environment","Fastify framework dependency","TypeScript compatibility for stripping types"],"zh":["需要 Node.js 环境","依赖 Fastify 框架","TypeScript 兼容性以去除类型"],"ja":["Node.js 環境が必要","Fastify フレームワークへの依存","タイプをストリップするための TypeScript 互換性"],"ko":["Node.js 환경이 필요함","Fastify 프레임워크 의존성","타입을 제거하기 위한 TypeScript 호환성"],"es":["Requiere entorno de Node.js","Dependencia del framework Fastify","Compatibilidad con TypeScript para la eliminación de tipos"],"fr":["Nécessite un environnement Node.js","Dépendance du framework Fastify","Compatibilité avec TypeScript pour le retrait de types"],"de":["Benötigt Node.js-Umgebung","Abhängigkeit vom Fastify-Framework","Kompatibilität mit TypeScript für die Entfernung von Typen"],"pt":["Requer ambiente Node.js","Dependência do framework Fastify","Compatibilidade com TypeScript para remoção de tipos"],"ru":["Требуется среда Node.js","Зависимость от фреймворка Fastify","Совместимость с TypeScript для удаления типов"],"ar":["يتطلب بيئة Node.js","اعتماد إطار Fastify","توافق مع TypeScript لإزالة الأنواع"]},"version":3},"qualityScore":50}');
