INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('boisenoise/skills-collections/wiki-vitepress', 'community', 'boisenoise', 'skills-collections', 'boisenoise/skills-collections', 'wiki-vitepress', 0, 0, 35, '2026-02-18T01:08:43.427Z', '2026-02-18T04:56:29.700Z', NULL, '{"id":"boisenoise/skills-collections/wiki-vitepress","name":"wiki-vitepress","description":{"zh":"VitePress Wiki 打包工具可以将生成的 wiki Markdown 文件转换为带有暗黑主题和交互式 Mermaid 图表的静态 VitePress 网站","ja":"VitePress Wiki パッケージャーは、生成された wiki Markdown ファイルをダークテーマと交互的な Mermaid 図を持つ静的 VitePress サイトに変換します","ko":"VitePress Wiki 패키저는 생성된 wiki Markdown 파일을 다크 테마와 상호 작용하는 Mermaid 다이어그램이 있는 정적 VitePress 사이트로 변환합니다","es":"El paquete Wiki VitePress transforma archivos Markdown de wiki en sitios web estáticos con VitePress. Incluye temas oscuros y diagramas Mermaid interactivos.","fr":"Le pack Wiki VitePress transforme des fichiers Markdown de wiki en sites web statiques avec VitePress. Il comprend des thèmes sombres et des diagrammes Mermaid interactifs.","de":"Das Wiki-VitePress-Paket wandelt Wiki-Markdown-Dateien in statische Webseiten mit VitePress um. Es beinhaltet dunkle Designs und interaktive Mermaid-Diagramme.","pt":"O Wiki VitePress Packager transforma arquivos Markdown do wiki em um site VitePress estático e interativo","ru":"Wiki VitePress Packager преобразует файлы Markdown wiki в статический интерактивный сайт VitePress","ar":"مجمع ويكي فيت بريس يحول ملفات Markdown من الويكي إلى موقع فيت بريس ثابت وتفاعلي","en":"Getting Skills Together to Learn from the Best"},"seo":{"title":{"zh":"VitePress Wiki 打包工具","ja":"VitePress Wiki パッケージャー","ko":"VitePress Wiki 패키저","es":"Wiki VitePress: Crea sitios web estáticos con Markdown","fr":"Wiki VitePress : Créez des sites web statiques avec Markdown","de":"Wiki VitePress: Erstelle statische Webseiten mit Markdown","pt":"Wiki VitePress Packager: Crie um site estático","ru":"Wiki VitePress Packager: Создайте静ический сайт","ar":"مجمع ويكي فيت بريس: انشئ موقعاً ثابتاً","en":"wiki-vitepress"},"description":{"zh":"VitePress Wiki 打包工具可以将生成的 wiki Markdown 文件转换为带有暗黑主题和交互式 Mermaid 图表的静态 VitePress 网站","ja":"VitePress Wiki パッケージャーは、生成された wiki Markdown ファイルをダークテーマと交互的な Mermaid 図を持つ静的 VitePress サイトに変換します","ko":"VitePress Wiki 패키저는 생성된 wiki Markdown 파일을 다크 테마와 상호 작용하는 Mermaid 다이어그램이 있는 정적 VitePress 사이트로 변환합니다","es":"El paquete Wiki VitePress transforma archivos Markdown de wiki en sitios web estáticos con VitePress. Incluye temas oscuros y diagramas Mermaid interactivos.","fr":"Le pack Wiki VitePress transforme des fichiers Markdown de wiki en sites web statiques avec VitePress. Il comprend des thèmes sombres et des diagrammes Merma...","de":"Das Wiki-VitePress-Paket wandelt Wiki-Markdown-Dateien in statische Webseiten mit VitePress um. Es beinhaltet dunkle Designs und interaktive Mermaid-Diagramme.","pt":"O Wiki VitePress Packager transforma arquivos Markdown do wiki em um site VitePress estático e interativo","ru":"Wiki VitePress Packager преобразует файлы Markdown wiki в статический интерактивный сайт VitePress","ar":"مجمع ويكي فيت بريس يحول ملفات Markdown من الويكي إلى موقع فيت بريس ثابت وتفاعلي","en":"Getting Skills Together to Learn from the Best"},"definition":{"en":"Getting Skills Together to Learn from the Best"},"features":{"zh":["支持暗黑主题","支持 Mermaid 图表","生成静态 VitePress 网站","支持 Markdown 文件转换","交互式图表"],"ja":["ダークテーマをサポート","Mermaid 図をサポート","静的 VitePress サイトを生成","Markdown ファイルを変換","交互的な図"],"ko":["다크 테마 지원","Mermaid 다이어그램 지원","정적 VitePress 사이트 생성","Markdown 파일 변환","상호 작용 다이어그램"],"es":["Transformación de archivos Markdown de wiki en sitios web estáticos","Soporte para temas oscuros","Diagramas Mermaid interactivos","Estructura de sitio web generada en el directorio wiki-site/","Compatibilidad con comando /deep-wiki:build"],"fr":["Transformation de fichiers Markdown de wiki en sites web statiques","Prise en charge de thèmes sombres","Diagrammes Mermaid interactifs","Structure de site web générée dans le répertoire wiki-site/","Compatibilité avec la commande /deep-wiki:build"],"de":["Umwandlung von Wiki-Markdown-Dateien in statische Webseiten","Unterstützung für dunkle Designs","Interaktive Mermaid-Diagramme","Seitenstruktur im wiki-site/-Verzeichnis generiert","Kompatibilität mit dem Befehl /deep-wiki:build"],"pt":["Gera sites estáticos a partir de arquivos Markdown do wiki","Inclui tema escuro e diagramas Mermaid interativos","Cria estrutura de site em um diretório wiki-site/","Suporta comandos de build e saída HTML","Oferece configuração personalizada com config.mts"],"ru":["Генерирует статические сайты из файлов Markdown wiki","Включает темную тему и интерактивные диаграммы Mermaid","Создает структуру сайта в директории wiki-site/","Поддерживает команды сборки и вывод HTML","Предоставляет настраиваемую конфигурацию с config.mts"],"ar":["ينشئ مواقعاً ثابتة من ملفات Markdown من الويكي","يضم مخططات ميرميد التفاعلية وسمة مظلمة","ينشئ هيكلاً لموقع في目录 wiki-site/","يدعم أوامر البناء ومخرجات HTML","يوفر ضبطاً قابل للتعديل مع config.mts"]},"keywords":{"zh":["VitePress","wiki","Markdown","静态网站","暗黑主题","Mermaid 图表"],"ja":["VitePress","wiki","Markdown","静的サイト","ダークテーマ","Mermaid 図"],"ko":["VitePress","wiki","Markdown","정적 사이트","다크 테마","Mermaid 다이어그램"],"es":["wiki vitepress","sitios web estáticos","markdown","vitepress","temas oscuros","diagramas mermaid","desarrollo web","herramientas de desarrollo"],"fr":["wiki vitepress","sites web statiques","markdown","vitepress","thèmes sombres","diagrammes mermaid","développement web","outils de développement"],"de":["wiki vitepress","statische webseiten","markdown","vitepress","dunkle designs","mermaid-diagramme","webentwicklung","entwicklungstools"],"pt":["wiki vitepress","site estático","markdown","vitepress","tema escuro","diagramas mermaid","desenvolvimento web","ferramentas de desenvolvimento"],"ru":["wiki vitepress","статический сайт","markdown","vitepress","темная тема","диаграммы mermaid","веб-разработка","инструменты разработки"],"ar":["ويكي فيت بريس","موقع ثابت","ماركداون","فيت بريس","سمة مظلمة","مخططات ميرميد","تطوير الويب","أدوات التطوير"]}},"owner":"boisenoise","repo":"skills-collections","repoPath":"boisenoise/skills-collections","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.427Z","topics":[],"category":"community","skillMd":{"name":"wiki-vitepress","description":"Packages generated wiki Markdown into a VitePress static site with dark theme, dark-mode Mermaid diagrams with click-to-zoom, and production build output. Use when the user wants to create a browsable website from generated wiki pages.","bodyPreview":"# Wiki VitePress Packager\n\nTransform generated wiki Markdown files into a polished VitePress static site with dark theme and interactive Mermaid diagrams.\n\n## When to Activate\n\n- User asks to \"build a site\" or \"package as VitePress\"\n- User runs the `/deep-wiki:build` command\n- User wants a browsable HTML output from generated wiki pages\n\n## VitePress Scaffolding\n\nGenerate the following structure in a `wiki-site/` directory:\n\n```\nwiki-site/\n├── .vitepress/\n│   ├── config.mts\n│   └── theme/\n│","body":"# Wiki VitePress Packager\n\nTransform generated wiki Markdown files into a polished VitePress static site with dark theme and interactive Mermaid diagrams.\n\n## When to Activate\n\n- User asks to \"build a site\" or \"package as VitePress\"\n- User runs the `/deep-wiki:build` command\n- User wants a browsable HTML output from generated wiki pages\n\n## VitePress Scaffolding\n\nGenerate the following structure in a `wiki-site/` directory:\n\n```\nwiki-site/\n├── .vitepress/\n│   ├── config.mts\n│   └── theme/\n│       ├── index.ts\n│       └── custom.css\n├── public/\n├── [generated .md pages]\n├── package.json\n└── index.md\n```\n\n## Config Requirements (`config.mts`)\n\n- Use `withMermaid` wrapper from `vitepress-plugin-mermaid`\n- Set `appearance: ''dark''` for dark-only theme\n- Configure `themeConfig.nav` and `themeConfig.sidebar` from the catalogue structure\n- Mermaid config must set dark theme variables:\n\n```typescript\nmermaid: {\n  theme: ''dark'',\n  themeVariables: {\n    primaryColor: ''#1e3a5f'',\n    primaryTextColor: ''#e0e0e0'',\n    primaryBorderColor: ''#4a9eed'',\n    lineColor: ''#4a9eed'',\n    secondaryColor: ''#2d4a3e'',\n    tertiaryColor: ''#2d2d3d'',\n    background: ''#1a1a2e'',\n    mainBkg: ''#1e3a5f'',\n    nodeBorder: ''#4a9eed'',\n    clusterBkg: ''#16213e'',\n    titleColor: ''#e0e0e0'',\n    edgeLabelBackground: ''#1a1a2e''\n  }\n}\n```\n\n## Dark-Mode Mermaid: Three-Layer Fix\n\n### Layer 1: Theme Variables (in config.mts)\nSet via `mermaid.themeVariables` as shown above.\n\n### Layer 2: CSS Overrides (`custom.css`)\nTarget Mermaid SVG elements with `!important`:\n\n```css\n.mermaid .node rect,\n.mermaid .node circle,\n.mermaid .node polygon { fill: #1e3a5f !important; stroke: #4a9eed !important; }\n.mermaid .edgeLabel { background-color: #1a1a2e !important; color: #e0e0e0 !important; }\n.mermaid text { fill: #e0e0e0 !important; }\n.mermaid .label { color: #e0e0e0 !important; }\n```\n\n### Layer 3: Inline Style Replacement (`theme/index.ts`)\nMermaid inline `style` attributes override everything. Use `onMounted` + polling to replace them:\n\n```typescript\nimport { onMounted } from ''vue''\n\n// In setup()\nonMounted(() => {\n  let attempts = 0\n  const fix = setInterval(() => {\n    document.querySelectorAll(''.mermaid svg [style]'').forEach(el => {\n      const s = (el as HTMLElement).style\n      if (s.fill && !s.fill.includes(''#1e3a5f'')) s.fill = ''#1e3a5f''\n      if (s.stroke && !s.stroke.includes(''#4a9eed'')) s.stroke = ''#4a9eed''\n      if (s.color) s.color = ''#e0e0e0''\n    })\n    if (++attempts >= 20) clearInterval(fix)\n  }, 500)\n})\n```\n\nUse `setup()` with `onMounted`, NOT `enhanceApp()` — DOM doesn''t exist during SSR.\n\n## Click-to-Zoom for Mermaid Diagrams\n\nWrap each `.mermaid` container in a clickable wrapper that opens a fullscreen modal:\n\n```typescript\ndocument.querySelectorAll(''.mermaid'').forEach(el => {\n  el.style.cursor = ''zoom-in''\n  el.addEventListener(''click'', () => {\n    const modal = document.createElement(''div'')\n    modal.className = ''mermaid-zoom-modal''\n    modal.innerHTML = el.outerHTML\n    modal.addEventListener(''click'', () => modal.remove())\n    document.body.appendChild(modal)\n  })\n})\n```\n\nModal CSS:\n```css\n.mermaid-zoom-modal {\n  position: fixed; inset: 0;\n  background: rgba(0,0,0,0.9);\n  display: flex; align-items: center; justify-content: center;\n  z-index: 9999; cursor: zoom-out;\n}\n.mermaid-zoom-modal .mermaid { transform: scale(1.5); }\n```\n\n## Post-Processing Rules\n\nBefore VitePress build, scan all `.md` files and fix:\n- Replace `<br/>` with `<br>` (Vue template compiler compatibility)\n- Wrap bare `<T>` generic parameters in backticks outside code fences\n- Ensure every page has YAML frontmatter with `title` and `description`\n\n## Build\n\n```bash\ncd wiki-site && npm install && npm run docs:build\n```\n\nOutput goes to `wiki-site/.vitepress/dist/`.\n\n## Known Gotchas\n\n- Mermaid renders async — SVGs don''t exist when `onMounted` fires. Must poll.\n- `isCustomElement` compiler option for bare `<T>` causes worse crashes — do NOT use it\n- Node text in Mermaid uses inline `style` with highest specificity — CSS alone won''t fix it\n- `enhanceApp()` runs during SSR where `document` doesn''t exist — use `setup()` only\n"},"lastSynced":"2026-02-18T04:56:29.700Z","agentAnalysis":{"suitability":{"en":"Perfect for Documentation Agents needing to transform wiki Markdown files into polished static sites with interactive Mermaid diagrams.","zh":"非常适合需要将 wiki Markdown 文件转换为带有交互式 Mermaid 图表的完善静态站点的文档代理。","ja":"ドキュメントエージェントが wiki Markdown ファイルをインタラクティブな Mermaid 図を備えた完成度の高い静的サイトに変換する必要がある場合に最適です。","ko":"위키 마크다운 파일을 상호작용형 머메이드 다이어그램이 포함된 정적인 사이트로 변환해야 하는 문서 에이전트에 적합합니다.","es":"Perfecto para agentes de documentación que necesitan transformar archivos Markdown de wiki en sitios estáticos pulidos con diagramas Mermaid interactivos.","fr":"Parfait pour les agents de documentation ayant besoin de transformer des fichiers Markdown de wiki en sites statiques polissés avec des diagrammes Mermaid interactifs.","de":"Perfekt für Dokumentationsagenten, die Wiki-Markdown-Dateien in polierte statische Seiten mit interaktiven Mermaid-Diagrammen umwandeln müssen.","pt":"Perfeito para Agentes de Documentação que precisam transformar arquivos Markdown do wiki em sites estáticos polidos com diagramas Mermaid interativos.","ru":"Идеально подходит для агентов документации, которым необходимо преобразовывать файлы Markdown wiki в отполированные статические сайты с интерактивными диаграммами Mermaid.","ar":"مثالي للوكلاء التعليمة الذين يحتاجون إلى تحويل ملفات Markdown من ويكي إلى مواقع ثابتة متطورة مع رسومات ميرميد تفاعلية."},"recommendation":{"en":"Empowers agents to generate browsable HTML outputs from wiki pages using VitePress, complete with dark themes and interactive Mermaid diagrams, by scaffolding a `wiki-site/` directory with customized `.vitepress/` configurations.","zh":"通过为 `wiki-site/` 目录提供自定义的 `.vitepress/` 配置，启用代理生成带有暗黑主题和交互式 Mermaid 图表的可浏览的 HTML 输出，使用 VitePress 从 wiki 页面中生成。","ja":"VitePress を使用して wiki ページから暗黒テーマとインタラクティブな Mermaid 図を備えた閲覧可能な HTML 出力を生成し、`wiki-site/` ディレクトリにカスタマイズされた `.vitepress/` 構成を提供することでエージェントを強化します。","ko":"VitePress를 사용하여 위키 페이지에서暗색 테마와 상호작용형 머메이드 다이어그램이 포함된 브라우저 가능한 HTML 출력을 생성하고 `wiki-site/` 디렉토리에 사용자 지정된 `.vitepress/` 구성 파일을 제공하여 에이전트를 강화합니다.","es":"Habilita a los agentes a generar salidas HTML navegables a partir de páginas de wiki utilizando VitePress, completas con temas oscuros y diagramas Mermaid interactivos, al crear un directorio `wiki-site/` con configuraciones personalizadas `.vitepress/`.","fr":"Permet aux agents de générer des sorties HTML navigables à partir de pages wiki en utilisant VitePress, complètes avec des thèmes sombres et des diagrammes Mermaid interactifs, en créant un répertoire `wiki-site/` avec des configurations personnalisées `.vitepress/`.","de":"Ermächtigt Agenten, mit VitePress browsbare HTML-Ausgaben aus Wiki-Seiten zu generieren, komplett mit dunklen Designs und interaktiven Mermaid-Diagrammen, indem ein `wiki-site/`-Verzeichnis mit benutzerdefinierten `.vitepress/`-Konfigurationen erstellt wird.","pt":"Habilita os agentes a gerar saídas HTML navegáveis a partir de páginas do wiki usando VitePress, completo com temas escuros e diagramas Mermaid interativos, ao criar uma estrutura de diretório `wiki-site/` com configurações personalizadas `.vitepress/`.","ru":"Наделяет агентов возможностью генерировать просматриваемые выходные данные HTML из страниц wiki с использованием VitePress, полные темными темами и интерактивными диаграммами Mermaid, путем создания структуры директории `wiki-site/` с настраиваемыми конфигурациями `.vitepress/`.","ar":"يمنح الوكلاء القدرة على توليد مخرجات HTML قابلة للملاحة من صفحات ويكي باستخدام VitePress ، كاملة مع темات داكنة ورسومات ميرميد تفاعلية ، من خلال إنشاء هيكل لمجلد `wiki-site/` مع تكوينات مخصصة `.vitepress/`."},"useCases":{"en":["Transforming wiki Markdown files into VitePress static sites","Generating interactive Mermaid diagrams for documentation","Creating browsable HTML outputs from generated wiki pages"],"zh":["将 wiki Markdown 文件转换为 VitePress 静态站点","为文档生成交互式 Mermaid 图表","从生成的 wiki 页面创建可浏览的 HTML 输出"],"ja":["wiki Markdown ファイルを VitePress 静的サイトに変換する","ドキュメント用のインタラクティブな Mermaid 図を生成する","生成された wiki ページから閲覧可能な HTML 出力を作成する"],"ko":["위키 마크다운 파일을 VitePress 정적인 사이트로 변환","문서를 위한 상호작용형 머메이드 다이어그램을 생성","생성된 위키 페이지에서 브라우저 가능한 HTML 출력을 생성"],"es":["Transformar archivos Markdown de wiki en sitios estáticos VitePress","Generar diagramas Mermaid interactivos para la documentación","Crear salidas HTML navegables a partir de páginas de wiki generadas"],"fr":["Transformer des fichiers Markdown de wiki en sites statiques VitePress","Générer des diagrammes Mermaid interactifs pour la documentation","Créer des sorties HTML navigables à partir de pages wiki générées"],"de":["Wiki-Markdown-Dateien in VitePress-Statikseiten umwandeln","Interaktive Mermaid-Diagramme für die Dokumentation generieren","Browsbare HTML-Ausgaben aus generierten Wiki-Seiten erstellen"],"pt":["Transformar arquivos Markdown do wiki em sites estáticos VitePress","Gerar diagramas Mermaid interativos para documentação","Criar saídas HTML navegáveis a partir de páginas do wiki geradas"],"ru":["Преобразовывать файлы Markdown wiki в статические сайты VitePress","Генерировать интерактивные диаграммы Mermaid для документации","Создавать просматриваемые выходные данные HTML из сгенерированных страниц wiki"],"ar":["تحويل ملفات Markdown من ويكي إلى مواقع ثابتة VitePress","توليد رسومات ميرميد تفاعلية للتوثيق","إنشاء مخرجات HTML قابلة للملاحة من صفحات ويكي المولدة"]},"limitations":{"en":["Requires generated wiki Markdown files","VitePress specific","Needs `/deep-wiki:build` command or specific user requests to activate"],"zh":["需要生成的 wiki Markdown 文件","VitePress 特定","需要 `/deep-wiki:build` 命令或特定的用户请求来激活"],"ja":["生成された wiki Markdown ファイルが必要","VitePress 固有"," `/deep-wiki:build` コマンドまたは特定のユーザー要求が必要"],"ko":["생성된 위키 마크다운 파일이 필요","VitePress 전용"," `/deep-wiki:build` 명령 또는 특정 사용자 요청이 필요"],"es":["Requiere archivos Markdown de wiki generados","Específico de VitePress","Necesita el comando `/deep-wiki:build` o solicitudes de usuario específicas para activar"],"fr":["Nécessite des fichiers Markdown de wiki générés","Spécifique à VitePress","Nécessite la commande `/deep-wiki:build` ou des demandes d''utilisateur spécifiques pour activer"],"de":["Benötigt generierte Wiki-Markdown-Dateien","VitePress-spezifisch","Benötigt den Befehl `/deep-wiki:build` oder spezifische Benutzeranfragen zum Aktivieren"],"pt":["Requer arquivos Markdown do wiki gerados","Específico do VitePress","Necessita do comando `/deep-wiki:build` ou solicitações específicas do usuário para ativar"],"ru":["Требует сгенерированных файлов Markdown wiki","Специфичен для VitePress","Требует команды `/deep-wiki:build` или конкретных запросов пользователя для активации"],"ar":["يتطلب ملفات Markdown من ويكي المولدة","محدد لبرنامج VitePress","يحتاج إلى أمر `/deep-wiki:build` أو طلبات محددة من المستخدم لتنشيطه"]},"version":3},"qualityScore":35}');
