INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agude/agude.github.io/copyedit', 'community', 'agude', 'agude.github.io', 'agude/agude.github.io', 'copyedit', 0, 0, 50, '2026-02-18T01:08:43.429Z', '2026-02-18T05:02:57.523Z', NULL, '{"id":"agude/agude.github.io/copyedit","name":"copyedit","description":{"zh":"copyedit 技能提供语法和风格编辑功能，帮助开发者改进文档质量","ja":"copyedit スキルは文法とスタイルの編集機能を提供し、開発者が文書の品質を向上させるのに役立ちます","ko":"copyedit 기능은 문법 및 스타일 편집 기능을 제공하여 개발자가 문서 품질을 향상시킬 수 있도록 합니다","es":"La herramienta de edición de copias es una herramienta en línea que ayuda a los desarrolladores a mejorar la claridad y coherencia de sus textos.","fr":"L''outil de correction de copies est un outil en ligne qui aide les développeurs à améliorer la clarté et la cohérence de leurs textes.","de":"Das Copyedit-Tool ist ein Online-Tool, das Entwicklern hilft, die Klarheit und Kohärenz ihrer Texte zu verbessern.","pt":"O Copyedit é uma ferramenta para edição de textos que ajuda a melhorar a clareza e a coerência dos textos, preservando a voz e o estilo do autor.","ru":"Copyedit - это инструмент для редактирования текстов, который помогает улучшить ясность и связность текстов, сохраняя голос и стиль автора.","ar":"Copyedit هي أداة لتحرير النصوص تساعد على تحسين وضوح وترابط النصوص، مع الحفاظ على صوت ونمط الكاتب.","en":"My personal website"},"seo":{"title":{"zh":"copyedit 技能：语法和风格编辑","ja":"copyedit スキル：文法とスタイルの編集","ko":"copyedit 기능: 문법 및 스타일 편집","es":"Herramienta de edición de copias para desarrolladores","fr":"Outil de correction de copies pour développeurs","de":"Copyedit-Tool für Entwickler","pt":"Copyedit: Edição de Textos para Desenvolvedores","ru":"Copyedit: Редактирование текстов для разработчиков","ar":"Copyedit: تحرير النصوص للمطورين","en":"copyedit"},"description":{"zh":"copyedit 技能提供语法和风格编辑功能，帮助开发者改进文档质量","ja":"copyedit スキルは文法とスタイルの編集機能を提供し、開発者が文書の品質を向上させるのに役立ちます","ko":"copyedit 기능은 문법 및 스타일 편집 기능을 제공하여 개발자가 문서 품질을 향상시킬 수 있도록 합니다","es":"La herramienta de edición de copias es una herramienta en línea que ayuda a los desarrolladores a mejorar la claridad y coherencia de sus textos.","fr":"L''outil de correction de copies est un outil en ligne qui aide les développeurs à améliorer la clarté et la cohérence de leurs textes.","de":"Das Copyedit-Tool ist ein Online-Tool, das Entwicklern hilft, die Klarheit und Kohärenz ihrer Texte zu verbessern.","pt":"O Copyedit é uma ferramenta para edição de textos que ajuda a melhorar a clareza e a coerência dos textos, preservando a voz e o estilo do autor.","ru":"Copyedit - это инструмент для редактирования текстов, который помогает улучшить ясность и связность текстов, сохраняя голос и стиль автора.","ar":"Copyedit هي أداة لتحرير النصوص تساعد على تحسين وضوح وترابط النصوص، مع الحفاظ على صوت ونمط الكاتب.","en":"My personal website"},"definition":{"en":"My personal website"},"features":{"zh":["语法检查","拼写检查","风格编辑","保持原有声音和风格","支持多种编辑模式"],"ja":["文法チェック","スペルチェック","スタイル編集","オリジナルの声とスタイルの維持","複数の編集モードのサポート"],"ko":["문법 검사","맞춤법 검사","스타일 편집","원래 목소리와 스타일 유지","다중 편집 모드 지원"],"es":["Corrección de errores gramaticales y de puntuación","Mejora de la claridad y coherencia de los textos","Preservación del estilo y la voz del autor","Modos de edición: gramática y pulido","Interfaz fácil de usar"],"fr":["Correction des erreurs grammaticales et de ponctuation","Amélioration de la clarté et de la cohérence des textes","Préservation du style et de la voix de l''auteur","Modes d''édition : grammaire et polissage","Interface facile à utiliser"],"de":["Korrektur von grammatischen und Punktuationsfehlern","Verbesserung der Klarheit und Kohärenz von Texten","Erhaltung des Stils und der Stimme des Autors","Bearbeitungsmodi: Grammatik und Polieren","Benutzerfreundliche Oberfläche"],"pt":["Edição de textos para melhorar a clareza e a coerência","Preservação da voz e do estilo do autor","Modos de edição: gramática e polimento","Correção de erros de ortografia e gramática","Melhoria da estrutura e da organização do texto"],"ru":["Редактирование текстов для улучшения ясности и связности","Сохранение голоса и стиля автора","Режимы редактирования: грамматика и полировка","Исправление ошибок орфографии и грамматики","Улучшение структуры и организации текста"],"ar":["تحرير النصوص لتحسين الوضوح والترابط","الحفاظ على صوت ونمط الكاتب","أوضاع التحرير: قواعد وتنمية","تصحيح أخطاء الإملاء والقواعد","تحسين هيكل وتنظيم النص"]},"keywords":{"zh":["copyedit","语法检查","拼写检查","风格编辑","编辑技能","文档编辑","开发者工具"],"ja":["copyedit","文法チェック","スペルチェック","スタイル編集","編集スキル","文書編集","開発者ツール"],"ko":["copyedit","문법 검사","맞춤법 검사","스타일 편집","편집 기능","문서 편집","개발자 도구"],"es":["edición de copias","corrección de textos","herramienta de edición en línea","desarrollo de contenido","claridad y coherencia","estilo y voz","gramática y puntuación"],"fr":["correction de copies","correction de textes","outil de correction en ligne","développement de contenu","clarté et cohérence","style et voix","grammaire et ponctuation"],"de":["Copyeditierung","Textkorrektur","Online-Editierwerkzeug","Inhaltsentwicklung","Klarheit und Kohärenz","Stil und Stimme","Grammatik und Punktuierung"],"pt":["copyedit","edição de textos","desenvolvedores","clareza","coerência","voz","estilo","gramática","polimento"],"ru":["copyedit","редактирование текстов","разработчики","ясность","связность","голос","стиль","грамматика","полировка"],"ar":["copyedit","تحرير النصوص","مطورين","وضوح","ترابط","صوت","نمط","قواعد","تنمية"]}},"owner":"agude","repo":"agude.github.io","repoPath":"agude/agude.github.io","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.429Z","topics":[],"category":"community","skillMd":{"name":"copyedit","description":"Edit blog posts and book reviews. Use `/copyedit grammar` for spelling/grammar only, or `/copyedit polish` for fuller editing. Preserves the authors voice and style.","bodyPreview":"# Copyedit Skill\n\nEdit drafts for alexgude.com while preserving voice and style.\n\n## Usage\n\n- `/copyedit grammar` --- Fix only spelling, grammar, and punctuation. Change nothing else.\n- `/copyedit polish` --- Fix errors, improve clarity, reword for coherence. Preserve voice.\n\nIf no mode is specified, ask which mode to use.\n\n## Instructions\n\n### Grammar Mode\n\nFix ONLY:\n- Spelling errors\n- Grammar mistakes (subject-verb agreement, tense consistency)\n- Punctuation errors\n- Typos\n\n### Polish Mode\n\nF","body":"# Copyedit Skill\n\nEdit drafts for alexgude.com while preserving voice and style.\n\n## Usage\n\n- `/copyedit grammar` --- Fix only spelling, grammar, and punctuation. Change nothing else.\n- `/copyedit polish` --- Fix errors, improve clarity, reword for coherence. Preserve voice.\n\nIf no mode is specified, ask which mode to use.\n\n## Instructions\n\n### Grammar Mode\n\nFix ONLY:\n- Spelling errors\n- Grammar mistakes (subject-verb agreement, tense consistency)\n- Punctuation errors\n- Typos\n\n### Polish Mode\n\nFollow this prompt:\n> Fix errors, make it clearer. Reword to make the arguments and sentences more coherent. Use the same sort of words I''m using, don''t substitute fancy synonyms. Maintain my voice.\n\nYou may:\n- Fix all grammar/spelling issues\n- Restructure sentences for clarity\n- Improve flow between ideas\n- Cut unnecessary words\n\nYou must:\n- Preserve the author''s vocabulary---don''t upgrade \"good\" to \"exceptional\"\n- Keep the same level of formality\n- Maintain opinions and judgments as written\n- Preserve all Liquid tags and formatting exactly\n\n## Output Format\n\nAdd the edited copy to the bottom of the article, separated by a markdown HR break.\n\nFor grammar mode, just change in place, and also list the changes made so the author can review them.\n\n## Voice & Style Guide\n\nSee [references/STYLE.md](references/STYLE.md) for the complete style guide.\n\nKey points:\n- **Tone**: First-person, conversational but substantive, direct and opinionated\n- **Vocabulary**: Simple, direct words. \"great\", \"fun\", \"loved\"---not \"exceptional\", \"delightful\", \"adored\"\n- **Hedging**: Avoid. Say \"I didn''t like it\" not \"I perhaps didn''t fully appreciate it\"\n- **Em-dashes**: Do NOT add em-dashes. LLMs overuse them. Only keep existing ones if appropriate.\n- **Contractions**: Use naturally, don''t insert needlessly.\n- **Oxford comma**: Yes\n\n### Anti-patterns (never do these)\n\n- Don''t add too many em-dashes (---)\n- Don''t add emojis\n- Don''t add exclamation marks unless the original has them\n- Don''t use \"delve\", \"tapestry\", \"nuanced\", \"compelling\"\n- Don''t add hedging words (\"perhaps\", \"somewhat\", \"rather\")\n- Don''t make it sound more formal or academic\n- Don''t add superlatives or intensifiers\n\n## Book Review Structure\n\nSee [references/BOOK-REVIEWS.md](references/BOOK-REVIEWS.md) for details on book review structure.\n\nKey constraints:\n- **First paragraph**: Uses `{{ page.title }}`, `{{ page.book_authors }}`, etc. No custom plugin tags. This paragraph is pulled out for social media previews, so it must stand alone.\n- **After first paragraph**: `{% capture %}` blocks define template variables, then prose continues using those variables.\n- **Paragraph 2 transition**: The challenge is prose flow---don''t repeat too much of what paragraph 1 just said. Find a new angle or continue the thought. Generally the author has already tried to do this but help them a bit.\n- **References to other works**: These create backlinks, so mentioning other books/authors is encouraged, but again the author will have filled in most of these. You may suggest others.\n\n## Plugin Reference\n\nSee [references/PLUGINS.md](references/PLUGINS.md) for the full plugin reference.\n\nCommon tags you''ll encounter:\n- `{% book_link \"Title\" %}` --- link to a book\n- `{% author_link \"Name\" %}` --- link to an author (supports `possessive`, `link_text=`)\n- `{% series_link \"Series\" %}` --- link to a series\n- `{% capture var %}...{% endcapture %}` --- define reusable variables\n\nDo not modify these tags. Preserve them exactly as written.\n"},"lastSynced":"2026-02-18T05:02:57.523Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing advanced text refinement capabilities, such as grammar and punctuation correction.","zh":"非常适合需要高级文本精炼功能的语言代理，例如语法和标点符号更正。","ja":"高度なテキストの洗練能力が必要な言語エージェントに最適です。たとえば、文法と句読点の修正などです。","ko":"문법 및 구두점 수정과 같은 고급 텍스트 세부 사항 기능이 필요한 언어 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Lenguaje que necesitan capacidades de refinamiento de texto avanzadas, como corrección de gramática y puntuación.","fr":"Parfait pour les Agents de Langage ayant besoin de capacités de raffinement de texte avancées, telles que la correction de grammaire et de ponctuation.","de":"Perfekt für Sprachagenten, die erweiterte Textverfeinerungsfunktionen benötigen, wie Grammatik- und Satzzeichenkorrektur.","pt":"Perfeito para Agentes de Linguagem que necessitam de capacidades avançadas de refinamento de texto, como correção de gramática e pontuação.","ru":"Идеально для языковых агентов, которым требуются расширенные возможности для доработки текста, такие как исправление грамматики и пунктуации.","ar":"مثالي للوكلاء اللغويين الذين يحتاجون إلى إمكانيات متقدمة لتحسين النص، مثل تصحيح القواعد والنقاط"},"recommendation":{"en":"Empowers agents to refine drafts using grammar and polish modes, preserving voice and style, and leveraging techniques like subject-verb agreement and tense consistency to improve clarity and coherence.","zh":"赋予代理人使用语法和抛光模式来精炼草稿的能力，同时保持声音和风格，并利用主谓一致和时态一致等技术来提高清晰度和连贯性。","ja":"エージェントに、文法とポリッシュモードを使用して草稿を洗練し、声やスタイルを保持し、主語と動詞の一致や時制の一貫性などのテクニックを利用して、明確性と一貫性を高める能力を付与します。","ko":"에이전트가 문법 및 광부 모드를 사용하여 초안을 다듬고 声音 및 스타일을 유지하며 주어-동사 일치 및 시제 일치와 같은 기술을 활용하여 명확성 및 일관성을 향상시키는 기능을 제공합니다.","es":"Habilita a los agentes a refinar borradores utilizando modos de gramática y pulido, preservando la voz y el estilo, y aprovechando técnicas como la concordancia sujeto-verbo y la coherencia de tiempo para mejorar la claridad y la coherencia.","fr":"Permet aux agents de raffiner les brouillons en utilisant les modes grammaire et polissage, en préservant la voix et le style, et en exploitant des techniques comme l''accord sujet-verbe et la cohérence des temps pour améliorer la clarté et la cohérence.","de":"Ermächtigt die Agenten, Entwürfe unter Verwendung von Grammatik- und Politurmodi zu verfeinern, wobei die Stimme und der Stil erhalten bleiben und Techniken wie die Übereinstimmung zwischen Subjekt und Verb sowie die Konsistenz der Zeit verwendet werden, um Klarheit und Kohärenz zu verbessern.","pt":"Habilita os agentes a refinar rascunhos usando modos de gramática e polir, preservando a voz e o estilo, e aproveitando técnicas como concordância sujeito-verbo e consistência de tempo para melhorar a clareza e a coerência.","ru":"Наделяет агентов возможностью дорабатывать черновики с помощью режимов грамматики и полировки, сохраняя голос и стиль, и используя техники, такие как согласование субъекта и глагола и последовательность времени, чтобы улучшить ясность и связность.","ar":"يمنح الوكلاء القدرة على تحسين المسودات باستخدام أوضاع القواعد والتنقية، مع الحفاظ على الصوت والأسلوب، واستخدام تقنيات مثل الاتفاق بين الفاعل والفعل والاتساق الزمني لتحسين الوضوح والترابط"},"useCases":{"en":["Refining blog posts for grammar and punctuation","Polishing website content for improved clarity","Editing drafts to preserve author voice and style"],"zh":["为博客文章更正语法和标点符号","为网站内容提高清晰度而进行抛光","编辑草稿以保持作者的声音和风格"],"ja":["ブログ記事の文法と句読点の修正","ウェブサイトのコンテンツを明確にするためにポリッシュ","草稿を編集して著者の声やスタイルを保持"],"ko":["블로그 게시물의 문법 및 구두점 수정","웹사이트 콘텐츠의 명확성을 높이기 위한 광부","초안 편집을 통해 저자의 목소리 및 스타일 유지"],"es":["Refinar publicaciones de blog para gramática y puntuación","Pulir el contenido del sitio web para mejorar la claridad","Editar borradores para preservar la voz y el estilo del autor"],"fr":["Raffiner les billets de blog pour la grammaire et la ponctuation","Polir le contenu du site Web pour améliorer la clarté","Éditer les brouillons pour préserver la voix et le style de l''auteur"],"de":["Verfeinern von Blog-Beiträgen für Grammatik und Satzzeichen","Polieren von Website-Inhalten zur Verbesserung der Klarheit","Bearbeiten von Entwürfen, um die Stimme und den Stil des Autors zu erhalten"],"pt":["Aperfeiçoar postagens de blog para gramática e pontuação","Polir conteúdo de sites para melhorar a clareza","Editar rascunhos para preservar a voz e o estilo do autor"],"ru":["Уточнить блог-посты по грамматике и пунктуации","Отполировать контент сайта для улучшения ясности","Редактировать черновики, чтобы сохранить голос и стиль автора"],"ar":["تحسين منشورات المدونة للقواعد والنقاط","تنقية محتوى الموقع لتحسين الوضوح","تحرير المسودات للحفاظ على صوت وأسلوب الكاتب"]},"limitations":{"en":["Requires specific mode selection (grammar or polish)","Limited to text-based content editing"],"zh":["需要选择特定的模式（语法或抛光）","仅限于基于文本的内容编辑"],"ja":["特定のモード（文法またはポリッシュ）の選択が必要","テキストベースのコンテンツ編集に限定"],"ko":["특정 모드(문법 또는 광부)의 선택이 필요","텍스트 기반 콘텐츠 편집에 제한"],"es":["Requiere una selección de modo específica (gramática o pulido)","Limitado a la edición de contenido basado en texto"],"fr":["Nécessite une sélection de mode spécifique (grammaire ou polissage)","Limité à l''édition de contenu basé sur le texte"],"de":["Erfordert eine spezifische Modusaufwahl (Grammatik oder Politur)","Begrenzt auf die Bearbeitung von textbasiertem Inhalt"],"pt":["Requer seleção de modo específico (gramática ou polir)","Limitado à edição de conteúdo baseado em texto"],"ru":["Требует выбора специального режима (грамматика или полировка)","Ограничен редактированием текстового контента"],"ar":["يتطلب اختيار وضع محدد (قواعد أو تنقية)","محدود بالتحرير المحتوى القائم على النص"]},"version":3},"qualityScore":50}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lbb00/ai-rules-sync/update-docs', 'community', 'lbb00', 'ai-rules-sync', 'lbb00/ai-rules-sync', 'update-docs', 0, 0, 65, '2026-02-18T01:08:43.428Z', '2026-02-18T05:02:51.824Z', NULL, '{"id":"lbb00/ai-rules-sync/update-docs","name":"update-docs","description":{"zh":"update-docs技能提供了一键式文档更新功能，帮助开发者轻松管理和共享AI规则、技能、命令和文档","ja":"update-docsスキルは、一括でドキュメントを更新する機能を提供し、開発者がAIルール、スキル、コマンド、ドキュメントを管理しやすくします","ko":"update-docs 스킬은 원클릭으로 문서를 업데이트하는 기능을 제공하여 개발자가 AI 규칙, 스킬, 명령 및 문서를 쉽게 관리할 수 있습니다","es":"El skill ''update-docs'' sincroniza y actualiza la documentación del proyecto después de los cambios de código","fr":"Le skill ''update-docs'' synchronise et met à jour la documentation du projet après les modifications de code","de":"Das ''update-docs''-Skill synchronisiert und aktualisiert die Projekt-Dokumentation nach Code-Änderungen","pt":"O skill update-docs sincroniza e gerencia suas regras de IA, habilidades e comandos com facilidade.","ru":"Навык update-docs позволяет синхронизировать и управлять своими правилами ИИ, навыками и командами.","ar":"مهارة تحديث المستندات تزامن وتدير قواعد_IA، المهارات والأوامر بسهولة","en":"Synchronize, manage, and share your ai rules, skills, commands, subagents (Cursor, Claude Code, Copilot, OpenCode, Trae AI, Codex, Gemini CLI, Warp) with ease."},"seo":{"title":{"zh":"更新文档 - 一键式文档更新","ja":"ドキュメント更新 - 一括更新","ko":"문서 업데이트 - 원클릭 업데이트","es":"Actualizar documentación de proyecto","fr":"Mettre à jour la documentation de projet","de":"Aktualisieren der Projekt-Dokumentation","pt":"Atualize Documentação com Facilidade","ru":"Обновление документации в один клик","ar":"تحديث المستندات بسهولة","en":"update-docs"},"description":{"zh":"update-docs技能提供了一键式文档更新功能，帮助开发者轻松管理和共享AI规则、技能、命令和文档","ja":"update-docsスキルは、一括でドキュメントを更新する機能を提供し、開発者がAIルール、スキル、コマンド、ドキュメントを管理しやすくします","ko":"update-docs 스킬은 원클릭으로 문서를 업데이트하는 기능을 제공하여 개발자가 AI 규칙, 스킬, 명령 및 문서를 쉽게 관리할 수 있습니다","es":"El skill ''update-docs'' sincroniza y actualiza la documentación del proyecto después de los cambios de código","fr":"Le skill ''update-docs'' synchronise et met à jour la documentation du projet après les modifications de code","de":"Das ''update-docs''-Skill synchronisiert und aktualisiert die Projekt-Dokumentation nach Code-Änderungen","pt":"O skill update-docs sincroniza e gerencia suas regras de IA, habilidades e comandos com facilidade.","ru":"Навык update-docs позволяет синхронизировать и управлять своими правилами ИИ, навыками и командами.","ar":"مهارة تحديث المستندات تزامن وتدير قواعد_IA، المهارات والأوامر بسهولة","en":"Synchronize, manage, and share your ai rules, skills, commands, subagents (Cursor, Claude Code, Copilot, OpenCode, Trae AI, Codex, Gemini CLI, Warp) with ease."},"definition":{"en":"Synchronize, manage, and share your ai rules, skills, commands, subagents (Cursor, Claude Code, Copilot, OpenCode, Trae AI, Codex, Gemini CLI, Warp) with ease."},"features":{"zh":["一键式文档更新","自动分析代码变更","支持多种AI规则和技能","轻松管理和共享文档","支持多种文档格式"],"ja":["一括でドキュメントを更新","自動でコードの変更を分析","複数のAIルールとスキルをサポート","ドキュメントを簡単に管理と共有","複数のドキュメント形式をサポート"],"ko":["원클릭으로 문서 업데이트","자동으로 코드 변경 분석","여러 가지 AI 규칙과 스킬 지원","문서를 쉽게 관리하고 공유","여러 가지 문서 형식 지원"],"es":["Actualización automática de la documentación","Análisis de cambios en el código","Actualización de la base de conocimiento","Actualización del archivo README","Compatibilidad con varios subagentes"],"fr":["Mise à jour automatique de la documentation","Analyse des modifications de code","Mise à jour de la base de connaissances","Mise à jour du fichier README","Compatibilité avec plusieurs sous-agents"],"de":["Automatische Aktualisierung der Dokumentation","Analyse von Code-Änderungen","Aktualisierung der Wissensbasis","Aktualisierung der README-Datei","Kompatibilität mit mehreren Subagenten"],"pt":["Análise de alterações de código","Atualização automática da documentação","Gerenciamento de regras de IA e habilidades","Integração com comandos e subagentes","Atualização de arquivos de conhecimento e leitura"],"ru":["Анализ изменений кода","Автоматическое обновление документации","Управление правилами ИИ и навыками","Интеграция с командами и субагентами","Обновление файлов знаний и чтения"],"ar":["تحليل تغييرات الشفرة","تحديث تلقائي للتوثيق","إدارة قواعد_IA والمهارات","تكامل مع الأوامر والوكالات الفرعية","تحديث ملفات المعرفة والقراءة"]},"keywords":{"zh":["更新文档","AI规则","AI技能","文档管理","代码变更","自动更新","一键式更新"],"ja":["ドキュメント更新","AIルール","AIスキル","ドキュメント管理","コード変更","自動更新","一括更新"],"ko":["문서 업데이트","AI 규칙","AI 스킬","문서 관리","코드 변경","자동 업데이트","원클릭 업데이트"],"es":["actualización de documentación","automatización de documentación","desarrollo de software","gestión de documentación","subagentes de AI","sincronización de documentación"],"fr":["mise à jour de documentation","automatisation de documentation","développement de logiciels","gestion de documentation","sous-agents d''IA","synchronisation de documentation"],"de":["Dokumenten-Aktualisierung","Dokumenten-Automatisierung","Software-Entwicklung","Dokumenten-Management","Subagenten von KI","Dokumenten-Synchronisierung"],"pt":["atualização de documentação","gerenciamento de regras de IA","desenvolvimento de software","ferramentas de desenvolvimento","documentação de projeto","skills de IA"],"ru":["обновление документации","управление правилами ИИ","разработка программного обеспечения","инструменты разработки","документация проекта","навыки ИИ"],"ar":["تحديث المستندات","إدارة قواعد_IA","تطوير البرمجيات","أدوات التطوير","توثيق المشروع","مهارات_IA"]}},"owner":"lbb00","repo":"ai-rules-sync","repoPath":"lbb00/ai-rules-sync","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.428Z","topics":[],"category":"community","skillMd":{"name":"update-docs","description":"Update all project documentation after code changes.","bodyPreview":"# Update Documentation\n\n## Instructions\n\nOne-click command to update all project documentation after code changes.\n\n### Steps\n\n1. **Analyze Changes**\n   - Check git status for modified files\n   - Review recent commits if no uncommitted changes\n   - Identify what documentation needs updating\n\n2. **Update KNOWLEDGE_BASE.md**\n   - Run the `update-knowledge-base` skill\n   - Document any architectural or feature changes\n\n3. **Update README.md**\n   - Add new features or commands\n   - Update examples i","body":"# Update Documentation\n\n## Instructions\n\nOne-click command to update all project documentation after code changes.\n\n### Steps\n\n1. **Analyze Changes**\n   - Check git status for modified files\n   - Review recent commits if no uncommitted changes\n   - Identify what documentation needs updating\n\n2. **Update KNOWLEDGE_BASE.md**\n   - Run the `update-knowledge-base` skill\n   - Document any architectural or feature changes\n\n3. **Update README.md**\n   - Add new features or commands\n   - Update examples if API changed\n   - Ensure accuracy of all documented commands\n\n4. **Sync README_ZH.md**\n   - Run the `sync-readme` skill\n   - Ensure Chinese documentation matches English\n\n5. **Verify**\n   - Run tests to ensure nothing broken: `npm test`\n   - Check that all documented commands work\n   - Review diff before committing\n\n### When to Use\n\n- After adding a new adapter\n- After adding or modifying CLI commands\n- After changing the configuration format\n- After any user-facing changes\n\n### Output\n\nAll documentation files updated and in sync:\n- KNOWLEDGE_BASE.md (if exists)\n- README.md\n- README_ZH.md\n\n## Examples\n\nRequest: Update all docs after adding OpenCode support\nResult: KNOWLEDGE_BASE.md, README.md, and README_ZH.md all updated\n"},"lastSynced":"2026-02-18T05:02:51.824Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents like Cursor, Claude Code, and AutoGPT needing automated documentation updates for efficient knowledge base management.","zh":"适合于需要自动更新文档以高效管理知识库的开发者代理，如 Cursor、Claude Code 和 AutoGPT。","ja":"自動ドキュメント更新が必要な開発者エージェント（Cursor、Claude Code、AutoGPT など）に最適です。","ko":"자동 문서 업데이트가 필요한 개발자 에이전트(Cursor, Claude Code, AutoGPT 등)에 적합합니다.","es":"Ideal para Agentes de Desarrollador como Cursor, Claude Code y AutoGPT que necesitan actualizaciones automatizadas de documentación para una gestión eficiente de la base de conocimientos.","fr":"Idéal pour les agents de développement tels que Cursor, Claude Code et AutoGPT nécessitant des mises à jour automatiques de la documentation pour une gestion efficace de la base de connaissances.","de":"Ideal für Entwickleragenten wie Cursor, Claude Code und AutoGPT, die automatisierte Dokumentenaktualisierungen für eine effiziente Wissensbasenverwaltung benötigen.","pt":"Ideal para Agentes de Desenvolvedor como Cursor, Claude Code e AutoGPT que precisam de atualizações automatizadas de documentação para um gerenciamento eficiente da base de conhecimento.","ru":"Идеально подходит для агентов-разработчиков, таких как Cursor, Claude Code и AutoGPT, которым необходимы автоматические обновления документации для эффективного управления базой знаний.","ar":"مثالي لعميل المطور مثل Cursor و Claude Code و AutoGPT الذي يحتاج إلى تحديثات وثائقية آليّة لإدارة قاعدة المعرفة بكفاءة."},"recommendation":{"en":"Empowers agents to synchronize and manage AI rules, skills, and commands by updating KNOWLEDGE_BASE.md and README.md files using git status checks and recent commit reviews, streamlining documentation processes with protocols like git.","zh":"赋予代理更新和管理 AI 规则、技能和命令的能力，通过 git 状态检查和最近提交审查来更新 KNOWLEDGE_BASE.md 和 README.md 文件，使用 git 等协议简化文档流程。","ja":"エージェントに AI ルール、スキル、コマンドを更新および管理する機能を提供し、git 状態チェックと最近のコミットレビューを使用して KNOWLEDGE_BASE.md と README.md ファイルを更新し、git などのプロトコルで文書化プロセスを簡素化します。","ko":"에이전트가 AI 규칙, 스킬 및 명령을 업데이트하고 관리할 수 있도록 하며, git 상태 체크 및 최근 커밋 리뷰를 통해 KNOWLEDGE_BASE.md 및 README.md 파일을 업데이트하고, git 등의 프로토콜로 문서화 프로세스를 단순화합니다.","es":"Permite a los agentes sincronizar y gestionar reglas de IA, habilidades y comandos actualizando los archivos KNOWLEDGE_BASE.md y README.md mediante comprobaciones de estado de git y revisiones de confirmación recientes, racionalizando los procesos de documentación con protocolos como git.","fr":"Permet aux agents de synchroniser et de gérer les règles d''IA, les compétences et les commandes en mettant à jour les fichiers KNOWLEDGE_BASE.md et README.md à l''aide de vérifications de statut git et d''examen de commit récents, rationalisant les processus de documentation avec des protocoles tels que git.","de":"Ermöglicht es den Agenten, AI-Regeln, Fähigkeiten und Befehle zu synchronisieren und zu verwalten, indem die Dateien KNOWLEDGE_BASE.md und README.md mithilfe von git-Statusprüfungen und aktuellen Commit-Überprüfungen aktualisiert werden, wodurch die Dokumentationsprozesse mit Protokollen wie git rationalisiert werden.","pt":"Habilita os agentes a sincronizar e gerenciar regras de IA, habilidades e comandos atualizando os arquivos KNOWLEDGE_BASE.md e README.md usando verificações de status do git e revisões de commits recentes, racionalizando os processos de documentação com protocolos como o git.","ru":"Наделяет агентов возможностью синхронизировать и управлять правилами ИИ, навыками и командами, обновляя файлы KNOWLEDGE_BASE.md и README.md с помощью проверок статуса git и обзоров недавних коммитов, оптимизируя процессы документации с помощью протоколов, таких как git.","ar":"يمكن للوكلاء من مزامنة وإدارة قواعد الذكاء الاصطناعي وال مهارات والأوامر عن طريق تحديث ملفات KNOWLEDGE_BASE.md وREADME.md باستخدام فحوصات حالة جيت ومراجعة التعديلات الحديثة، وتبسيط عمليات توثيق بالبروتوكولات مثل جيت."},"useCases":{"en":["Automating documentation updates after code changes","Generating updated README.md files with new features","Synchronizing KNOWLEDGE_BASE.md with recent architectural changes"],"zh":["代码更改后自动更新文档","生成带有新功能的更新 README.md 文件","将 KNOWLEDGE_BASE.md 与最近的架构更改同步"],"ja":["コード変更後にドキュメントを自動更新","新しい機能を含む README.md ファイルを生成","KNOWLEDGE_BASE.md を最近のアーキテクチャ変更と同期"],"ko":["코드 변경 후 자동으로 문서 업데이트하기","새로운 기능을 포함하는 README.md 파일 생성하기","KNOWLEDGE_BASE.md를 최근의 아키텍처 변경과 동기화하기"],"es":["Automatizar las actualizaciones de documentación después de cambios de código","Generar archivos README.md actualizados con nuevas características","Sincronizar KNOWLEDGE_BASE.md con cambios arquitectónicos recientes"],"fr":["Automatiser les mises à jour de la documentation après des modifications de code","Générer des fichiers README.md mis à jour avec de nouvelles fonctionnalités","Synchroniser KNOWLEDGE_BASE.md avec des changements architecturaux récents"],"de":["Automatisieren von Dokumentenaktualisierungen nach Codeänderungen","Erstellen von aktualisierten README.md-Dateien mit neuen Funktionen","Synchronisieren von KNOWLEDGE_BASE.md mit aktuellen architektonischen Änderungen"],"pt":["Automatizar atualizações de documentação após alterações de código","Gerar arquivos README.md atualizados com recursos novos","Sincronizar KNOWLEDGE_BASE.md com alterações arquiteturais recentes"],"ru":["Автоматизировать обновления документации после изменений кода","Генерировать обновленные файлы README.md с новыми функциями","Синхронизировать KNOWLEDGE_BASE.md с недавними архитектурными изменениями"],"ar":["تتمة تحديثات وثائقية بعد تغييرات الشفرة","توليد ملفات README.md المحدثة مع الميزات الجديدة","مزامنة KNOWLEDGE_BASE.md مع التغييرات المعمارية الحديثة"]},"limitations":{"en":["Requires git integration","Limited to updating specific documentation files (KNOWLEDGE_BASE.md, README.md)"],"zh":["需要 git 集成","仅限更新特定文档文件（KNOWLEDGE_BASE.md、README.md）"],"ja":["git 統合が必要","特定のドキュメント ファイル（KNOWLEDGE_BASE.md、README.md）のみを更新可能"],"ko":["git 통합이 필요함","특정 문서 파일(KNOWLEDGE_BASE.md, README.md)만 업데이트할 수 있음"],"es":["Requiere integración con git","Limitado a la actualización de archivos de documentación específicos (KNOWLEDGE_BASE.md, README.md)"],"fr":["Nécessite une intégration avec git","Limité à la mise à jour de fichiers de documentation spécifiques (KNOWLEDGE_BASE.md, README.md)"],"de":["Benötigt eine Integration mit git","Begrenzt auf die Aktualisierung bestimmter Dokumentendateien (KNOWLEDGE_BASE.md, README.md)"],"pt":["Requer integração com o git","Limitado à atualização de arquivos de documentação específicos (KNOWLEDGE_BASE.md, README.md)"],"ru":["Требует интеграции с git","Ограничен обновлением только определенных файлов документации (KNOWLEDGE_BASE.md, README.md)"],"ar":["يتطلب التكامل مع جيت","محدود بالتحديث لملفات وثائقية محددة (KNOWLEDGE_BASE.md، README.md)"]},"version":3},"qualityScore":65}');
