INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('parcadei/Continuous-Claude-v3/slash-commands', 'community', 'parcadei', 'Continuous-Claude-v3', 'parcadei/Continuous-Claude-v3', 'slash-commands', 0, 0, 80, '2026-02-18T01:08:43.429Z', '2026-02-18T05:06:15.712Z', NULL, '{"id":"parcadei/Continuous-Claude-v3/slash-commands","name":"slash-commands","description":{"zh":"Slash 命令是 Claude Code 的上下文管理的一部分，允许开发者创建和使用用户触发的提示","ja":"スラッシュコマンドは、Claude Code のコンテキスト管理の一部であり、開発者がユーザー起動プロンプトを作成および使用できるようにします","ko":"슬래시 명령어는 Claude Code의 컨텍스트 관리의 일부로 개발자가 사용자 트리거 프롬프트를 생성하고 사용할 수 있도록 합니다","es":"Los comandos de barra permiten a los desarrolladores crear y utilizar comandos personalizados para gestionar contextos y mejorar la experiencia del usuario en Claude Code.","fr":"Les commandes de barre permettent aux développeurs de créer et d''utiliser des commandes personnalisées pour gérer les contextes et améliorer l''expérience utilisateur dans Claude Code.","de":"Die Slash-Befehle ermöglichen es Entwicklern, benutzerdefinierte Befehle zu erstellen und zu verwenden, um Kontexte zu verwalten und die Benutzererfahrung in Claude Code zu verbessern.","en":"Context management for Claude Code. Hooks maintain state via ledgers and handoffs. MCP execution without context pollution. Agent orchestration with isolated context windows."},"seo":{"title":{"zh":"Slash 命令参考 - Claude Code 上下文管理","ja":"スラッシュコマンドリファレンス - Claude Code コンテキスト管理","ko":"슬래시 명령어 참조 - Claude Code 컨텍스트 관리","es":"Comandos de barra para desarrolladores","fr":"Commandes de barre pour développeurs","de":"Slash-Befehle für Entwickler","en":"slash-commands"},"description":{"zh":"Slash 命令是 Claude Code 的上下文管理的一部分，允许开发者创建和使用用户触发的提示","ja":"スラッシュコマンドは、Claude Code のコンテキスト管理の一部であり、開発者がユーザー起動プロンプトを作成および使用できるようにします","ko":"슬래시 명령어는 Claude Code의 컨텍스트 관리의 일부로 개발자가 사용자 트리거 프롬프트를 생성하고 사용할 수 있도록 합니다","es":"Los comandos de barra permiten a los desarrolladores crear y utilizar comandos personalizados para gestionar contextos y mejorar la experiencia del usuario e...","fr":"Les commandes de barre permettent aux développeurs de créer et d''utiliser des commandes personnalisées pour gérer les contextes et améliorer l''expérience uti...","de":"Die Slash-Befehle ermöglichen es Entwicklern, benutzerdefinierte Befehle zu erstellen und zu verwenden, um Kontexte zu verwalten und die Benutzererfahrung in...","en":"Context management for Claude Code. Hooks maintain state via ledgers and handoffs. MCP execution without context pollution. Agent orchestration with isolated..."},"definition":{"en":"Context management for Claude Code. Hooks maintain state via ledgers and handoffs. MCP execution without context pollution. Agent orchestration with isolated context windows."},"features":{"zh":["创建和使用用户触发的提示","管理 Claude Code 的上下文","使用 /command-name 语法","内置命令（如 /clear、/compact、/config）","支持文件引用","与技能结合使用"],"ja":["ユーザー起動プロンプトの作成と使用","Claude Code のコンテキスト管理","/command-name 構文の使用","ビルトインコマンド（/clear、/compact、/config など）","ファイル参照のサポート","スキルとの統合"],"ko":["사용자 트리거 프롬프트의 생성 및 사용","Claude Code의 컨텍스트 관리","/command-name 구문의 사용","내장 명령어（/clear, /compact, /config 등）","파일 참조 지원","스킬과 함께 사용"],"es":["Creación de comandos personalizados","Gestión de contextos","Mejora de la experiencia del usuario","Compatibilidad con Claude Code","Uso de la sintaxis /command-name"],"fr":["Création de commandes personnalisées","Gestion de contextes","Amélioration de l''expérience utilisateur","Compatibilité avec Claude Code","Utilisation de la syntaxe /command-name"],"de":["Erstellung benutzerdefinierter Befehle","Kontextverwaltung","Verbesserung der Benutzererfahrung","Kompatibilität mit Claude Code","Verwendung der Syntax /command-name"]},"keywords":{"zh":["Slash 命令","Claude Code","上下文管理","用户触发提示","命令行接口","开发者工具","编程语言","软件开发","技术文档"],"ja":["スラッシュコマンド","Claude Code","コンテキスト管理","ユーザー起動プロンプト","コマンドラインインターフェース","開発者ツール","プログラミング言語","ソフトウェア開発","テクニカルドキュメント"],"ko":["슬래시 명령어","Claude Code","컨텍스트 관리","사용자 트리거 프롬프트","명령줄 인터페이스","개발자 도구","프로그래밍 언어","소프트웨어 개발","기술 문서"],"es":["comandos de barra","desarrollo de software","Claude Code","gestión de contextos","experiencia del usuario","programación","desarrolladores"],"fr":["commandes de barre","développement de logiciels","Claude Code","gestion de contextes","expérience utilisateur","programmation","développeurs"],"de":["Slash-Befehle","Software-Entwicklung","Claude Code","Kontextverwaltung","Benutzererfahrung","Programmierung","Entwickler"]}},"owner":"parcadei","repo":"Continuous-Claude-v3","repoPath":"parcadei/Continuous-Claude-v3","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.429Z","topics":[],"category":"community","skillMd":{"name":"slash-commands","description":"Create and use Claude Code slash commands - quick prompts, bash execution, file references","bodyPreview":"# Slash Commands Reference\n\nCreate and use user-triggered prompts with `/command-name` syntax.\n\n## When to Use\n\n- \"How do I create a slash command?\"\n- \"What slash commands are available?\"\n- \"Add bash to my command\"\n- \"Use file references in commands\"\n- \"Slash commands vs skills\"\n\n## Built-in Commands\n\n| Command | Purpose |\n|---------|---------|\n| `/clear` | Clear conversation history |\n| `/compact` | Compact conversation with focus |\n| `/config` | Open settings interface |\n| `/cost` | Show token","body":"# Slash Commands Reference\n\nCreate and use user-triggered prompts with `/command-name` syntax.\n\n## When to Use\n\n- \"How do I create a slash command?\"\n- \"What slash commands are available?\"\n- \"Add bash to my command\"\n- \"Use file references in commands\"\n- \"Slash commands vs skills\"\n\n## Built-in Commands\n\n| Command | Purpose |\n|---------|---------|\n| `/clear` | Clear conversation history |\n| `/compact` | Compact conversation with focus |\n| `/config` | Open settings interface |\n| `/cost` | Show token usage |\n| `/agents` | Manage sub-agents |\n| `/mcp` | Manage MCP servers |\n| `/memory` | Edit CLAUDE.md files |\n| `/model` | Select AI model |\n| `/review` | Request code review |\n| `/resume` | Resume session |\n| `/help` | Get usage help |\n\n## Creating Commands\n\n### Project Commands\n```bash\nmkdir -p .claude/commands\ncat > .claude/commands/optimize.md << ''EOF''\n---\ndescription: Analyze code for performance issues\n---\n\nReview this code for:\n- Performance bottlenecks\n- Memory leaks\n- Caching opportunities\nEOF\n```\n\n### Personal Commands\n```bash\nmkdir -p ~/.claude/commands\ncat > ~/.claude/commands/review.md << ''EOF''\n---\ndescription: Security-focused code review\n---\n\nCheck for vulnerabilities:\n- Input validation\n- SQL injection\n- XSS risks\nEOF\n```\n\n## Command File Format\n\n```yaml\n---\ndescription: Brief description for /help\nallowed-tools: [Bash, Read, Write]  # Optional\nargument-hint: \"[file] [type]\"       # Optional\n---\n\nYour markdown instructions here.\nUse $1, $2 for arguments or $ARGUMENTS for all.\n```\n\n## Bash Execution\n\nRun bash before loading prompt with `!` prefix:\n\n```yaml\n---\nallowed-tools: Bash(git:*), Bash(grep:*)\ndescription: Git commit helper\n---\n\nCurrent status: !`git status`\nStaged changes: !`git diff --staged`\nRecent commits: !`git log --oneline -5`\n\nBased on these changes, suggest a commit message.\n```\n\n**Rules:**\n- Must declare `allowed-tools: Bash(...)` in frontmatter\n- Use backticks: `` !`command` ``\n- Output is included in Claude''s context\n\n## File References\n\nInclude files with `@` prefix:\n\n```markdown\nReview against @.claude/STYLE_GUIDE.md\n\nCompare:\n- @src/old.js\n- @src/new.js\n\nRefactor files matching @src/**/*.util.ts\n```\n\n## Arguments\n\n```yaml\n---\nargument-hint: \"[pr-number] [priority]\"\n---\n\nReview PR #$1 with priority: $2\n\n# Or use all arguments:\nFix issue #$ARGUMENTS\n```\n\n**Usage:**\n```bash\n/review-pr 456 high\n# $1 = \"456\", $2 = \"high\"\n```\n\n## Namespacing\n\nOrganize with subdirectories:\n\n```\n.claude/commands/\n├── frontend/\n│   └── component.md    → /component (project:frontend)\n└── backend/\n    └── endpoint.md     → /endpoint (project:backend)\n```\n\n## MCP Slash Commands\n\nMCP servers expose prompts as commands:\n\n```bash\n/mcp__github__list_prs\n/mcp__github__pr_review 456\n/mcp__jira__create_issue \"Bug\" high\n```\n\n## Slash Commands vs Skills\n\n| Aspect | Slash Commands | Skills |\n|--------|----------------|--------|\n| Invocation | Explicit: `/command` | Auto-discovered |\n| Files | Single .md file | Directory with SKILL.md |\n| Use Case | Quick prompts | Complex workflows |\n\n**Use slash commands for:** Frequently typed prompts, simple templates\n**Use skills for:** Complex workflows, multiple files, auto-discovery\n\n## Example: Complete Git Commit Command\n\n```yaml\n---\ndescription: Generate semantic commit message\nallowed-tools: Bash(git:*), Read\nargument-hint: \"[type]\"\n---\n\n# Semantic Commit Generator\n\nStaged files: !`git diff --name-only --cached`\n\nDiff preview:\n!`git diff --cached | head -100`\n\nGenerate a conventional commit message.\nType: $1 (feat/fix/docs/style/refactor/perf/test/chore)\n\nFormat: `<type>(<scope>): <subject>`\n```\n\n**Usage:** `/commit feat`\n"},"lastSynced":"2026-02-18T05:06:15.712Z","agentAnalysis":{"suitability":{"en":"Ideal for Context Management Agents like Claude Code, requiring advanced state management via ledgers and handoffs.","zh":"适用于需要通过账本和交接管理高级状态的上下文管理代理，如Claude Code","ja":"Claude Codeのような、高度な状態管理をレジャーとハンドオフを介して行う必要があるコンテキスト管理エージェントに適しています","ko":"Claude Code와 같은 원장 및 인도를 통해 고급 상태 관리가 필요한 컨텍스트 관리 에이전트에 적합합니다","es":"Ideal para agentes de gestión de contexto como Claude Code, que requieren una gestión de estado avanzada a través de libros de registro y transferencias.","fr":"Idéal pour les agents de gestion de contexte comme Claude Code, nécessitant une gestion d''état avancée via des registres et des transferts.","de":"Ideal für Kontext-Management-Agents wie Claude Code, die eine erweiterte Zustandsverwaltung über Kontenbücher und Übergaben erfordern.","pt":"Ideal for Context Management Agents like Claude Code, requiring advanced state management via ledgers and handoffs.","ru":"Ideal for Context Management Agents like Claude Code, requiring advanced state management via ledgers and handoffs.","ar":"Ideal for Context Management Agents like Claude Code, requiring advanced state management via ledgers and handoffs."},"recommendation":{"en":"Empowers agents to execute MCP commands without context pollution, utilizing isolated context windows and slash command syntax like `/clear` and `/config`, while maintaining state via ledgers.","zh":"使代理能够在不污染上下文的情况下执行MCP命令，利用隔离的上下文窗口和斜杠命令语法，如 `/clear` 和 `/config` ，同时通过账本维护状态","ja":"エージェントがコンテキスト汚染なくMCPコマンドを実行できるようにし、 `/clear` や `/config` のようにスラッシュコマンド構文と分離されたコンテキストウィンドウを使用する同时、レジャーを介して状態を維持します","ko":"에이전트가 컨텍스트 오염 없이 MCP 명령을 실행할 수 있도록 하며, `/clear` 및 `/config`와 같은 슬래시 명령어 구문을 사용하여 분리된 컨텍스트 창을 사용하고 원장을 통해 상태를 유지합니다","es":"Permite a los agentes ejecutar comandos MCP sin contaminación de contexto, utilizando ventanas de contexto aisladas y sintaxis de comandos con barra como `/clear` y `/config`, manteniendo el estado a través de libros de registro.","fr":"Permet aux agents d''exécuter des commandes MCP sans pollution de contexte, en utilisant des fenêtres de contexte isolées et une syntaxe de commande avec barre comme `/clear` et `/config`, tout en maintenant l''état via des registres.","de":"Ermöglicht es Agents, MCP-Befehle ohne Kontextverschmutzung auszuführen, indem sie isolierte Kontextfenster und Schragsyntax wie `/clear` und `/config` verwenden, während der Zustand über Kontenbücher aufrechterhalten wird.","pt":"Empowers agents to execute MCP commands without context pollution, utilizing isolated context windows and slash command syntax like `/clear` and `/config`, while maintaining state via ledgers.","ru":"Empowers agents to execute MCP commands without context pollution, utilizing isolated context windows and slash command syntax like `/clear` and `/config`, while maintaining state via ledgers.","ar":"Empowers agents to execute MCP commands without context pollution, utilizing isolated context windows and slash command syntax like `/clear` and `/config`, while maintaining state via ledgers."},"useCases":{"en":["Creating user-triggered prompts with custom slash commands","Managing conversation history with commands like `/clear` and `/compact`","Configuring agent settings with the `/config` command"],"zh":["使用自定义斜杠命令创建用户触发的提示","使用 `/clear` 和 `/compact` 等命令管理对话历史","使用 `/config` 命令配置代理设置"],"ja":["カスタムスラッシュコマンドを使用してユーザーによってトリガーされるプロンプトを作成する"," `/clear` や `/compact` などのコマンドを使用して会話履歴を管理する"," `/config` コマンドを使用してエージェント設定を構成する"],"ko":["사용자에 의해 트리거되는 프롬프트를 사용자 지정 슬래시 명령으로 생성하는 것"," `/clear` 및 `/compact`와 같은 명령을 사용하여 대화 기록을 관리하는 것"," `/config` 명령을 사용하여 에이전트 설정을 구성하는 것"],"es":["Crear solicitudes desencadenadas por el usuario con comandos personalizados con barra","Gestionar el historial de conversación con comandos como `/clear` y `/compact`","Configurar la configuración del agente con el comando `/config`"],"fr":["Créer des invites déclenchées par l''utilisateur avec des commandes personnalisées avec barre","Gérer l''historique de conversation avec des commandes comme `/clear` et `/compact`","Configurer les paramètres de l''agent avec la commande `/config`"],"de":["Erstellen von benutzertriggerten Prompts mit benutzerdefinierten Schragsbefehlen","Verwalten der Konversationshistorie mit Befehlen wie `/clear` und `/compact`","Konfigurieren der Agenteneinstellungen mit dem Befehl `/config`"],"pt":["Creating user-triggered prompts with custom slash commands","Managing conversation history with commands like `/clear` and `/compact`","Configuring agent settings with the `/config` command"],"ru":["Creating user-triggered prompts with custom slash commands","Managing conversation history with commands like `/clear` and `/compact`","Configuring agent settings with the `/config` command"],"ar":["Creating user-triggered prompts with custom slash commands","Managing conversation history with commands like `/clear` and `/compact`","Configuring agent settings with the `/config` command"]},"limitations":{"en":["Requires Claude Code integration","Context management limited to ledger and handoff mechanisms"],"zh":["需要Claude Code集成","上下文管理仅限于账本和交接机制"],"ja":["Claude Codeの統合が必要","コンテキスト管理はレジャーとハンドオフメカニズムに限定される"],"ko":["Claude Code 통합이 필요합니다","컨텍스트 관리는 원장 및 인도 메커니즘으로 제한됩니다"],"es":["Requiere integración con Claude Code","La gestión de contexto está limitada a mecanismos de libro de registro y transferencia"],"fr":["Nécessite une intégration avec Claude Code","La gestion de contexte est limitée aux mécanismes de registre et de transfert"],"de":["Erfordert Integration mit Claude Code","Die Kontextverwaltung ist auf Mechanismen von Kontenbüchern und Übergaben beschränkt"],"pt":["Requires Claude Code integration","Context management limited to ledger and handoff mechanisms"],"ru":["Requires Claude Code integration","Context management limited to ledger and handoff mechanisms"],"ar":["Requires Claude Code integration","Context management limited to ledger and handoff mechanisms"]},"version":3},"qualityScore":80}');
